    private void buildTaskFinished(Entry entry, SkillRunner.State state) {
        var task = entry.activeBuildTask;
        entry.activeBuildTask = null;
        // A table set down to craft at for the build's needs (E-08c) is its own to come back to, however often the build
        // planned again while it was being set down; the build's own table is the build's.
        boolean tableForNeeds = task != null && "native_place".equals(task.skill()) && "Place a crafting table".equals(task.label());
        if (task != null && entry.build != null && entry.nativeBody != null && entry.campaign != null && (entry.build.needsTask(task) || tableForNeeds)) {
            // A step for the build's needs (E-08c): the run's own gathering hears how it went.
            boolean completed = state == SkillRunner.State.COMPLETED;
            if (completed && "native_place".equals(task.skill())) {
                BlockPos placed = new BlockPos(Integer.parseInt(task.args().get("x")), Integer.parseInt(task.args().get("y")),
                        Integer.parseInt(task.args().get("z")));
                if (entry.nativeBody.entity().getServerWorld().getBlockState(placed).isOf(Blocks.CRAFTING_TABLE)) {
                    entry.campaign.placedWorkstation(placed);
                    entry.campaign.knowledge().remember(WorldKnowledge.Kind.CRAFTING_TABLE, placed);
                }
            }
            entry.campaign.taskFinished(task, completed, server.getTicks());
        }
        if (task != null && entry.field != null) {
            boolean completed = state == SkillRunner.State.COMPLETED;
            if (!completed) KindredMod.LOGGER.info("{} field step did not complete: {} [{}]", entry.data.displayName(),
                    entry.runner.reason().orElse(""), task.label());
            entry.field.finished(task, completed);
            entry.routineRefreshPending = true;
            entry.cachedRoutineCandidates = List.of();
            return;
        }
        if (task != null && (entry.ranch != null || entry.growing != null || entry.seeding != null) && entry.nativeBody != null) {
            var world = entry.nativeBody.entity().getServerWorld();
            boolean completed = state == SkillRunner.State.COMPLETED;
            if ("native_place".equals(task.skill()) && entry.campaign != null) {
                BlockPos placed = new BlockPos(Integer.parseInt(task.args().get("x")), Integer.parseInt(task.args().get("y")),
                        Integer.parseInt(task.args().get("z")));
                // A table it set down to craft the pen's fences or its hoe is its own to craft at again.
                if (completed && world.getBlockState(placed).isOf(Blocks.CRAFTING_TABLE)) {
                    entry.campaign.placedWorkstation(placed);
                    entry.campaign.knowledge().remember(WorldKnowledge.Kind.CRAFTING_TABLE, placed);
                }
                // One that would not go down there: not there again for a minute (M-01a).
                if (!completed) entry.campaign.setAside(placed, server.getTicks() + 1200);
            }
            if (!completed) KindredMod.LOGGER.info("{} ranch step did not complete: {} [{}]", entry.data.displayName(),
                    entry.runner.reason().orElse(""), task.label());
            if (entry.ranch != null) entry.ranch.finished(task, completed, entry.runner.reason().orElse(""), world);
            entry.routineRefreshPending = true;
            entry.cachedRoutineCandidates = List.of();
            return;
        }
        if (task == null || entry.build == null || entry.nativeBody == null) return;
        entry.build.finished(task, state == SkillRunner.State.COMPLETED, entry.runner.reason().orElse(""),
                entry.nativeBody.entity().getServerWorld());
        entry.routineRefreshPending = true;
        entry.cachedRoutineCandidates = List.of();
    }

    /**
     * Starts a build (E-08b): {@code blueprint} placed with its origin at {@code origin}, turned clockwise
     * {@code turns} quarters, built from the player's own blocks ahead of its standing goal. Null stops the build.
     */
    int startBuild(ServerCommandSource source, UUID id, dev.kindred.core.construction.Blueprint blueprint, BlockPos origin, int turns) {
        return startBuild(source, id, blueprint, origin, turns, null);
    }

    /**
     * As {@link #startBuild(ServerCommandSource, UUID, dev.kindred.core.construction.Blueprint, BlockPos, int)}, the
     * build kept for a restart under {@code plan}, the name the command gave it (F-13); with none it is not kept (a
     * base's build has its own record, a build battle's ends with the match).
     */
    int startBuild(ServerCommandSource source, UUID id, dev.kindred.core.construction.Blueprint blueprint, BlockPos origin, int turns, String plan) {
        requireThread();
        Entry entry = id != null ? entries.get(id) : null;
        if (entry == null || entry.nativeState == null || !nativeMayControl(source, entry)) {
            return reject(source, "Native player unavailable or administrative access denied.");
        }
        if (blueprint == null) {
            // A base's build stopped by its administrator is not taken up again at once (M-01c).
            if (entry.build != null && (entry.build == entry.baseBuild || entry.build == entry.hallBuild)) {
                entry.baseBuild = null;
                entry.baseRepair = null;
                entry.hallBuild = null;
                entry.hallRepair = false;
                entry.baseCheckAt = server.getTicks() + BASE_RETRY;
            }
            entry.build = null;
            entry.buildTasks.clear();
            keepWork(entry, null);
            entry.goalProgress = "";
            entry.cachedRoutineCandidates = List.of();
            entry.routineRefreshPending = true;
            feedback(source, entry.data.displayName() + ": the build is stopped; what is built stays.");
            return 1;
        }
        if (!worldEditsEnabled()) return reject(source, "AI world edits are disabled on this server; an operator must enable them first.");
        entry.build = new BuildRunner(blueprint, origin, turns);
        entry.keptScaffold = Set.of();
        keepWork(entry, plan == null || entry.nativeBody == null ? null : new PlayerMemoryStore.Work("build", plan,
                entry.nativeBody.entity().getServerWorld().getRegistryKey().getValue().toString(), origin.getX(), origin.getY(), origin.getZ(), turns, List.of()));
        entry.goalProgress = "Starting: " + blueprint.name();
        if (entry.runtimeSettings.playstyleProfile().isIdleObserving()) {
            entry.runtimeSettings = entry.runtimeSettings.withPlaystyle(PlaystyleProfile.OPTIMAL_SURVIVAL);
        }
        entry.manualHoldUntilTick = Long.MIN_VALUE;
        entry.cachedRoutineCandidates = List.of();
        entry.routineRefreshPending = true;
        var bill = dev.kindred.core.construction.BillOfMaterials.of(entry.build.blocks(), entry.build.snapshot(entry.nativeBody.entity().getServerWorld()),
                BuildRunner.counts(entry.nativeBody.entity()));
        String missing = bill.complete() ? "" : "; short of " + bill.missing();
        String unsupported = bill.unsupported().isEmpty() ? "" : "; no way to place yet: " + String.join(", ", bill.unsupported());
        if (entry.snapshot().stopLatched()) nativeLifecycle(source, "resume", id);
        feedback(source, entry.data.displayName() + ": building " + blueprint.name() + " (" + SchematicLibrary.credit(blueprint) + ") at "
                + origin.toShortString() + missing + unsupported + ".");
        return 1;
    }

    /** How often a player with no goal looks to its base (M-01c), after finding nowhere to put one, after a stage ended short. */
    private static final int BASE_LOOK = 200, BASE_NO_SITE = 1200, BASE_RETRY = 6000;
    /** A workstation cell let be after this many refused placements in a row, for this many ticks (F-22c77). */
    static final int PLACE_REFUSALS = 3, PLACE_SET_ASIDE = 1200;
    /** How far from its anchor a player looks for ground for a base, and how often a stage that ends short is tried. */
    private static final int BASE_RADIUS = 24, BASE_TRIES = 3;
    /** How far a player looks round it for animals to keep (M-01a); its wheat plot's side. */
    private static final int RANCH_LOOK = 32, PLOT = 2;

    /**
     * A player's own base (M-01c), with the operator's leave and AI world edits on, when it has no goal, build or ranch
     * of its own: a stage it began, taken up again where it stands; otherwise the next stage {@link
     * dev.kindred.core.construction.BaseProgression} calls for, on the nearest flat open ground ({@link
     * dev.kindred.core.construction.BaseSite}) to where it first looked, or beside its last base. The stage is then a
     * build like any other, its blocks fetched through its needs (E-08c). Whether it started a build.
     */
    private boolean baseDecision(Entry entry, NativePlayerBody body) {
        // Not before the work it was at before a restart is read: a base begun first would clear it (F-13).
        if (!bases || !worldEditsEnabled() || goalOf(entry) != dev.kindred.core.survival.SurvivalGoal.NONE || entry.build != null
                || entry.ranch != null || entry.field != null || entry.seeding != null || entry.growing != null || entry.stable != null
                || entry.snapshot().stopLatched() || entry.workRead != WorkRead.TAKEN) return false;
        var player = body.entity();
        var world = player.getServerWorld();
        if (world.getRegistryKey() != net.minecraft.world.World.OVERWORLD) return false;
        long now = server.getTicks();
        if (now < entry.baseCheckAt) return false;
        UUID id = entry.data.id();
        if (!basesLoaded(entry)) return false;
        entry.baseCheckAt = now + BASE_LOOK;

        String dimension = world.getRegistryKey().getValue().toString();
        var record = entry.bases;
        var last = record.built.isEmpty() ? null : record.built.get(record.built.size() - 1);
        if (last != null && !last.dimension().equals(dimension)) return false;
        if (last != null && !last.complete()) {
            return startBase(entry, last, "Back to its " + last.stage());
        }
        // What it built it keeps whole (E-31a): a stage with blocks gone or out of place (a chest broken, a wall blown
        // out) is built again on its own plan, which places only what is missing, its blocks fetched as any build's.
        for (var base : record.built) {
            if (!base.dimension().equals(dimension)) continue;
            int damage = baseDamage(world, base);
            if (damage > 0) {
                String why = "Repairing its " + base.stage() + ", " + damage + (damage == 1 ? " block" : " blocks") + " out of place";
                noteBase(entry, why);
                if (!startBase(entry, base, why)) return false;
                entry.baseRepair = base;
                return true;
            }
        }
        // Its trading hall kept whole as its base is (E-45d, E-31a): its own blocks gone or out of place put back, and
        // only those. What it keeps clear is left as it is (a cell's front shut with its villager's job block, the rail
        // on a cell's floor), and nothing is touched while it brings a villager home, whose line takes the door out.
        var standing = record.hall;
        if (standing != null && standing.complete() && standing.dimension().equals(dimension) && entry.bring == null) {
            int damage = hallDamage(world, standing);
            if (damage > 0) {
                String why = "Repairing its trading hall, " + damage + (damage == 1 ? " block" : " blocks") + " out of place";
                var plan = hallPlan(standing);
                var repair = new dev.kindred.core.construction.Blueprint("the trading hall's repair", plan.source(), plan.creator(), plan.license(),
                        plan.blocks(), List.of());
                if (startBuild(server.getCommandSource(), id, repair, new BlockPos(standing.x(), standing.y(), standing.z()), 0) != 1) return false;
                entry.hallBuild = entry.build;
                entry.hallRepair = true;
                noteBase(entry, why);
                return true;
            }
        }
        // A trading hall by its base once it keeps a villager worth a cell (E-45d), ahead of its next stage: one it
        // began taken up again, else sited on the nearest flat open ground to its base.
        if (last != null && last.complete()) {
            var hall = record.hall;
            if (hall != null && !hall.complete() && hall.dimension().equals(dimension)) return startHall(entry, hall, "Back to its trading hall");
            if (hall == null && keepsAVillager(entry, body)) {
                var before = footprint(last);
                var avoid = new java.util.ArrayList<dev.kindred.core.construction.BaseSite.Footprint>();
                for (var base : record.built) avoid.add(footprint(base));
                var site = dev.kindred.core.construction.BaseSite.choose(ground(world), (before.minX() + before.maxX()) / 2,
                        (before.minZ() + before.maxZ()) / 2, BASE_RADIUS, dev.kindred.core.construction.TradingHall.width(HALL_CELLS),
                        dev.kindred.core.construction.TradingHall.DEPTH, dev.kindred.core.construction.TradingHall.HEIGHT, avoid);
                if (site.isPresent()) {
                    record.hall = new PlayerMemoryStore.Hall(dimension, site.get().x(), site.get().y(), site.get().z(), HALL_CELLS,
                            styleOf(last).wood(), false);
                    memories.saveBases(id, record);
                    return startHall(entry, record.hall, "A villager worth keeping, and a cell to keep it in");
                }
                noteBase(entry, "No flat open ground for a trading hall within " + BASE_RADIUS + " blocks of its " + last.stage());
            }
        }
        var decision = dev.kindred.core.construction.BaseProgression.next(baseProgress(body, last));
        noteBase(entry, decision.why());
        // With nothing to build next, animals of its own (M-01a).
        if (decision.next().isEmpty()) return ranchDecision(entry, body, record, last, dimension);
        var stage = decision.next().get();
        // In Co-op Survival it keeps to the humans' pace (M-01e): no stage ahead of the furthest step any of them reached,
        // read afresh as it decides, not as the last poll left it.
        boolean paced = worldMode == dev.kindred.core.match.GameModes.WorldMode.COOP_SURVIVAL;
        if (paced) pollGroupPace();
        var held = dev.kindred.core.match.GroupPace.hold(stage, paced, java.util.Optional.ofNullable(groupStep));
        if (held.isPresent()) {
            noteBase(entry, held.get());
            return ranchDecision(entry, body, record, last, dimension);
        }
        if (record.anchor == null) {
            BlockPos home = entry.setup == null || entry.setup.home() == null ? player.getBlockPos()
                    : new BlockPos(entry.setup.home().position().x(), entry.setup.home().position().y(), entry.setup.home().position().z());
            record.anchor = new PlayerMemoryStore.Place(dimension, home.getX(), home.getY(), home.getZ());
        }
        int anchorX = record.anchor.x(), anchorZ = record.anchor.z();
        if (last != null) {
            var before = footprint(last);
            anchorX = (before.minX() + before.maxX()) / 2;
            anchorZ = (before.minZ() + before.maxZ()) / 2;
        }
        // Its style grown from its seed block, or the wood it has to hand, and its world (E-29a): this world's stage
        // is not the next world's.
        var style = entry.fixedBaseStyle != null ? entry.fixedBaseStyle : unique(entry, stage, dev.kindred.core.construction.BuildStyle.grown(record.seed,
                woodAtHand(entry, body), world.getSeed() ^ id.getMostSignificantBits() ^ id.getLeastSignificantBits() * 31 + stage.ordinal()));
        var shape = dev.kindred.core.construction.Houses.shape(stage, style.variant());
        int[] span = dev.kindred.core.construction.Houses.span(shape, style.turns());
        var plan = dev.kindred.core.construction.Houses.of(stage, style);
        var site = siteFor(world, record, dimension, anchorX, anchorZ, span[0], span[1], height(plan), footprint -> true);
        if (site.isEmpty()) {
            entry.baseCheckAt = now + BASE_NO_SITE;
            noteBase(entry, "No flat open ground for a " + stage.noun + " within " + BASE_RADIUS + " blocks of " + anchorX + ", " + anchorZ);
            return false;
        }
        var origin = dev.kindred.core.construction.Houses.originFor(site.get(), shape, style.turns());
        var base = new PlayerMemoryStore.Base(stage.noun, dimension, origin.x(), origin.y(), origin.z(), false,
                style.seed().isEmpty() ? null : style.seed(), style.wood(), style.variant(), style.turns());
        record.built.add(base);
        memories.saveBases(id, record);
        return startBase(entry, base, decision.why());
    }

    /**
     * A ranch of its own by its base (M-01a), once its first base stands whole: the first kind it has seen a pair of near
     * it and holds the food to breed (cows, sheep, pigs, then chickens), on the nearest flat open ground to its base, from
     * its own wood. One it began is taken up again; one that has run its course is not begun twice.
     */
    private boolean ranchDecision(Entry entry, NativePlayerBody body, PlayerMemoryStore.Bases record, PlayerMemoryStore.Base last, String dimension) {
        if (last == null || !last.complete()) return false;
        // A pen it began is taken up again; a kind it keeps, in a pen run or begun, is not kept twice (a pen per kind).
        var kept = java.util.EnumSet.noneOf(dev.kindred.core.survival.Ranch.Kind.class);
        for (var pen : record.allPens()) {
            if (!pen.dimension().equals(dimension)) continue;
            if (!pen.complete()) return startOwnRanch(entry, body, pen, "Back to its ranch");
            kept.add(dev.kindred.core.survival.Ranch.Kind.valueOf(pen.kind()));
        }
        // Its wheat plot tended: a cell left bare (trampled back to dirt by its animals, or its crop broken) sown again
        // with the seeds it holds, as a player keeps its field (the wheat fixture: one cell bare after the cows went by).
        if (tendDecision(entry, body, record, dimension)) return true;
        var player = body.entity();
        var seen = new java.util.EnumMap<dev.kindred.core.survival.Ranch.Kind, Integer>(dev.kindred.core.survival.Ranch.Kind.class);
        var food = new java.util.EnumMap<dev.kindred.core.survival.Ranch.Kind, Integer>(dev.kindred.core.survival.Ranch.Kind.class);
        // Only animals it can see from where it stands, or saw lately: nothing hidden is known. A herd that wandered off
        // while its wheat grew is the herd it saw (the wheat fixture: the cows out of sight by the harvest).
        long now = server.getTicks();
        for (var animal : player.getServerWorld().getEntitiesByClass(net.minecraft.entity.passive.AnimalEntity.class,
                player.getBoundingBox().expand(RANCH_LOOK), a -> !a.isBaby() && player.canSee(a))) {
            String type = Registries.ENTITY_TYPE.getId(animal.getType()).toString();
            for (var kind : dev.kindred.core.survival.Ranch.Kind.values()) {
                if (kind.entity.equals(type)) entry.herd.put(animal.getUuid(), new Sighting(kind, animal.getBlockPos().toImmutable(), now));
            }
        }
        entry.herd.values().removeIf(sighting -> now - sighting.tick() > HERD_MEMORY);
        for (var sighting : entry.herd.values()) seen.merge(sighting.kind(), 1, Integer::sum);
        var inventory = player.getInventory();
        for (var kind : dev.kindred.core.survival.Ranch.Kind.values()) {
            int held = 0;
            for (String item : kind.food) held += inventory.count(Registries.ITEM.get(Identifier.of(item)));
            food.put(kind, held);
        }
        var choice = dev.kindred.core.survival.RanchChoice.next(true, seen, food, SeedRunner.grassInSight(player), kept);
        if (choice.kind().isEmpty() && horseDecision(entry, body, record)) return true;
        if (choice.kind().isEmpty() && againDecision(entry, body, record, dimension, food)) return true;
        if (choice.kind().isEmpty() && choice.earn().isPresent() && choice.earn().get() == dev.kindred.core.survival.Ranch.Kind.PIG) {
            // The pigs' carrots or potatoes grown in the plot from one it holds (its beetroot is food, not planted).
            var held = player.getInventory();
            var crop = held.count(Items.CARROT) > 0 ? WheatRunner.Crop.CARROT : held.count(Items.POTATO) > 0 ? WheatRunner.Crop.POTATO : null;
            if (crop == null) {
                entry.ranchNote = "A pair of pigs close by; no carrot or potato to plant";
                return false;
            }
            return wheatDecision(entry, body, record, last, dimension, choice.why(), crop);
        }
        if (choice.kind().isEmpty() && choice.earn().isPresent() && choice.earn().get() != dev.kindred.core.survival.Ranch.Kind.CHICKEN) {
            // The cows' or sheep's wheat grown in a plot by its base; then the ranch, with it in hand.
            return wheatDecision(entry, body, record, last, dimension, choice.why(), WheatRunner.Crop.WHEAT);
        }
        if (choice.kind().isEmpty() && choice.earn().isPresent()) {
            // The chickens' seeds earned first, from the grass about it; then the ranch, with them in hand.
            entry.ranchNote = choice.why();
            entry.seeding = new SeedRunner(dev.kindred.core.survival.RanchChoice.EARN);
            entry.goalProgress = "Ranch: seeds first";
            entry.cachedRoutineCandidates = List.of();
            entry.routineRefreshPending = true;
            KindredMod.LOGGER.info("{} ranch: {}", entry.data.displayName(), choice.why());
            return true;
        }
        if (choice.kind().isEmpty()) {
            entry.ranchNote = choice.why();
            return false;
        }
        if (RanchRunner.woodOf(player) == null) {
            entry.ranchNote = "A pair of " + choice.kind().get().plural() + " to keep, and no wood for a pen's fences";
            return false;
        }
        var before = footprint(last);
        var avoid = new java.util.ArrayList<dev.kindred.core.construction.BaseSite.Footprint>();
        for (var base : record.built) if (base.dimension().equals(dimension)) avoid.add(footprint(base));
        if (record.hall != null && record.hall.dimension().equals(dimension)) avoid.add(footprint(record.hall));
        if (record.plot != null && record.plot.dimension().equals(dimension)) {
            avoid.add(new dev.kindred.core.construction.BaseSite.Footprint(record.plot.x(), record.plot.z(), record.plot.x() + PLOT - 1, record.plot.z() + PLOT - 1));
        }
        for (var pen : record.allPens()) {
            if (pen.dimension().equals(dimension)) avoid.add(new dev.kindred.core.construction.BaseSite.Footprint(pen.x(), pen.z(), pen.x() + 6, pen.z() + 6));
        }
        var site = dev.kindred.core.construction.BaseSite.choose(ground(player.getServerWorld()), (before.minX() + before.maxX()) / 2,
                (before.minZ() + before.maxZ()) / 2, BASE_RADIUS, 7, 7, 2, avoid);
        if (site.isEmpty()) {
            entry.ranchNote = "No flat open ground for a pen within " + BASE_RADIUS + " blocks of its " + last.stage();
            return false;
        }
        var pen = new PlayerMemoryStore.Pen(dimension, site.get().x(), site.get().y(), site.get().z(), choice.kind().get().name(), false);
        record.addPen(pen);
        memories.saveBases(entry.data.id(), record);
        return startOwnRanch(entry, body, pen, choice.why());
    }

    /**
     * More than a pair (M-01a): with no new kind to keep, a pen it keeps is taken up again to breed its grown animals once
     * more after their breeding wait, until it holds a herd. Only a pen it can see into from where it stands is counted:
     * nothing hidden is known. The first pen ready, oldest first.
     */
    private boolean againDecision(Entry entry, NativePlayerBody body, PlayerMemoryStore.Bases record, String dimension,
                                  java.util.Map<dev.kindred.core.survival.Ranch.Kind, Integer> food) {
        var player = body.entity();
        var world = player.getServerWorld();
        long now = world.getTime();
        String why = null;
        for (var pen : record.allPens()) {
            if (!pen.complete() || !pen.dimension().equals(dimension)) continue;
            var kind = dev.kindred.core.survival.Ranch.Kind.valueOf(pen.kind());
            BlockPos post = new BlockPos(pen.x(), pen.y(), pen.z());
            if (post.getSquaredDistance(player.getBlockPos()) > (double) RANCH_LOOK * RANCH_LOOK) continue;
            int adults = 0, young = 0;
            for (var animal : world.getEntitiesByClass(net.minecraft.entity.passive.AnimalEntity.class, new net.minecraft.util.math.Box(post).expand(8),
                    a -> a.getBlockX() > post.getX() && a.getBlockX() < post.getX() + 6 && a.getBlockZ() > post.getZ() && a.getBlockZ() < post.getZ() + 6
                            && Registries.ENTITY_TYPE.getId(a.getType()).toString().equals(kind.entity) && player.canSee(a))) {
                if (animal.isBaby()) young++;
                else adults++;
            }
            var again = dev.kindred.core.survival.RanchChoice.again(kind, adults, young, food.getOrDefault(kind, 0), now - pen.ranAt());
            if (again.breed()) return startOwnRanch(entry, body, pen, again.why());
            if (why == null) why = again.why();
        }
        if (why != null) entry.ranchNote = why;
        return false;
    }

    /**
     * The cows' or sheep's wheat grown (M-01a), or the pigs' carrots or potatoes from one it holds: its plot by its base, sited on the nearest flat open ground and kept with its
     * bases, worked until it holds the wheat; while the wheat grows it gets on with other things, and each look at its
     * base takes the plot up again.
     */
    private boolean wheatDecision(Entry entry, NativePlayerBody body, PlayerMemoryStore.Bases record, PlayerMemoryStore.Base last,
                                  String dimension, String why, WheatRunner.Crop crop) {
        var player = body.entity();
        if (record.plot == null || !record.plot.dimension().equals(dimension)) {
            var before = footprint(last);
            var avoid = new java.util.ArrayList<dev.kindred.core.construction.BaseSite.Footprint>();
            for (var base : record.built) if (base.dimension().equals(dimension)) avoid.add(footprint(base));
            if (record.hall != null && record.hall.dimension().equals(dimension)) avoid.add(footprint(record.hall));
            for (var pen : record.allPens()) {
                if (pen.dimension().equals(dimension)) avoid.add(new dev.kindred.core.construction.BaseSite.Footprint(pen.x(), pen.z(), pen.x() + 6, pen.z() + 6));
            }
            var site = dev.kindred.core.construction.BaseSite.choose(ground(player.getServerWorld()), (before.minX() + before.maxX()) / 2,
                    (before.minZ() + before.maxZ()) / 2, BASE_RADIUS, PLOT, PLOT, 1, avoid);
            if (site.isEmpty()) {
                entry.ranchNote = "No flat open ground for a wheat plot within " + BASE_RADIUS + " blocks of its " + last.stage();
                return false;
            }
            // The site's floor is laid on the ground; the plot is the ground itself, one below.
            record.plot = new PlayerMemoryStore.Plot(dimension, site.get().x(), site.get().y() - 1, site.get().z());
            memories.saveBases(entry.data.id(), record);
        }
        String wood = RanchRunner.woodOf(player);
        entry.growing = new WheatRunner(new BlockPos(record.plot.x(), record.plot.y(), record.plot.z()), PLOT,
                dev.kindred.core.survival.RanchChoice.EARN, wood == null ? "oak" : wood, crop);
        if (!why.equals(entry.ranchNote)) KindredMod.LOGGER.info("{} ranch: {}", entry.data.displayName(), why);
        entry.ranchNote = why;
        entry.cachedRoutineCandidates = List.of();
        entry.routineRefreshPending = true;
        return true;
    }

    /** Whether its wheat plot has a cell with no crop and it holds seeds to sow it; if so, the plot taken up again (M-01a). */
    private boolean tendDecision(Entry entry, NativePlayerBody body, PlayerMemoryStore.Bases record, String dimension) {
        if (record.plot == null || !record.plot.dimension().equals(dimension)) return false;
        var player = body.entity();
        if (player.getInventory().count(Items.WHEAT_SEEDS) == 0) return false;
        var world = player.getServerWorld();
        BlockPos corner = new BlockPos(record.plot.x(), record.plot.y(), record.plot.z());
        boolean bare = false;
        for (int dx = 0; dx < PLOT && !bare; dx++) for (int dz = 0; dz < PLOT && !bare; dz++) {
            BlockPos cell = corner.add(dx, 0, dz);
            var soil = world.getBlockState(cell);
            boolean ground = soil.isOf(Blocks.FARMLAND) || soil.isOf(Blocks.DIRT) || soil.isOf(Blocks.GRASS_BLOCK);
            bare = ground && !world.getBlockState(cell.up()).isOf(Blocks.WHEAT);
        }
        if (!bare) return false;
        String wood = RanchRunner.woodOf(player);
        entry.growing = new WheatRunner(corner, PLOT, 0, wood == null ? "oak" : wood);
        entry.ranchNote = "Its wheat plot tended: a bare cell sown again";
        entry.cachedRoutineCandidates = List.of();
        entry.routineRefreshPending = true;
        KindredMod.LOGGER.info("{} ranch: {}", entry.data.displayName(), entry.ranchNote);
        return true;
    }

    /** Its wheat plot's next step (M-01a), as one project candidate; survival needs still outrank it. */
    private List<NativeTaskCandidate> growCandidates(Entry entry, NativePlayerBody body) {
        var growing = entry.growing;
        if (entry.campaign == null) entry.campaign = new PortalRunCampaign();
        var task = growing.next(body, entry.campaign);
        if (!growing.progress().isEmpty()) entry.goalProgress = "Ranch: " + growing.progress();
        if (!entry.goalProgress.equals(entry.loggedGoalProgress)) {
            entry.loggedGoalProgress = entry.goalProgress;
            KindredMod.LOGGER.info("{} ranch: {}", entry.data.displayName(), growing.progress());
        }
        if (task.isEmpty()) {
            entry.growing = null;
            entry.buildTasks.clear();
            entry.ranchNote = growing.outcome();
            // Growing: looked at again with its base; with the wheat in hand, decided again at once.
            if (!growing.growing()) entry.baseCheckAt = 0;
            entry.routineRefreshPending = true;
            return List.of();
        }
        var t = task.get();
        UUID id = UUID.nameUUIDFromBytes(("wheat:" + entry.data.id() + ":" + t.skill() + ":" + new java.util.TreeMap<>(t.args()))
                .getBytes(StandardCharsets.UTF_8));
        entry.buildTasks.clear();
        entry.buildTasks.put(id, t);
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.PROJECT, 70.0,
                new dev.kindred.core.TaskPreferences.Affinities(0.0, 0.0, 0.0, 0.6), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(candidate, t.skill(), t.args()));
    }

    /** The wheat plot of its own (M-01a), for fixtures. */
    Optional<PlayerMemoryStore.Plot> plot(UUID id) {
        requireThread();
        Entry entry = id != null ? entries.get(id) : null;
        return entry == null || entry.bases == null ? Optional.empty() : Optional.ofNullable(entry.bases.plot);
    }

    /** Where and when it last saw a grown animal of a kind it might keep (M-01a). */
    private record Sighting(dev.kindred.core.survival.Ranch.Kind kind, BlockPos at, long tick) { }

    /** How long a sighting is remembered: five minutes, the time its wheat may take to grow and be harvested. */
    private static final long HERD_MEMORY = 6000;

    /** Its own ranch begun at its pen (M-01a), as the operator's command begins one. */
    private boolean startOwnRanch(Entry entry, NativePlayerBody body, PlayerMemoryStore.Pen pen, String why) {
        String wood = RanchRunner.woodOf(body.entity());
        if (wood == null) {
            entry.ranchNote = "Its ranch waits for wood for the pen's fences";
            return false;
        }
        var kind = dev.kindred.core.survival.Ranch.Kind.valueOf(pen.kind());
        entry.ranch = new RanchRunner(new BlockPos(pen.x(), pen.y(), pen.z()), kind, wood);
        // The ones it saw, to look for where it saw them last should they stray meanwhile.
        for (var sighting : entry.herd.entrySet()) {
            if (sighting.getValue().kind() != kind) continue;
            BlockPos at = sighting.getValue().at();
            entry.ranch.ranch.remember(sighting.getKey(), new dev.kindred.core.construction.Pos(at.getX(), at.getY(), at.getZ()));
        }
        entry.ownRanch = pen;
        entry.ranchNote = why;
        entry.goalProgress = "Ranch: starting";
        entry.cachedRoutineCandidates = List.of();
        entry.routineRefreshPending = true;
        KindredMod.LOGGER.info("{} ranch: {}: {} at {}, {}, {}", entry.data.displayName(), why, kind.plural(), pen.x(), pen.y(), pen.z());
        return true;
    }

    /**
     * Whether the player's record of its bases is read; if not, its reading begun, off the game thread. Its base (M-01c)
     * and its trading hall's villagers (E-45e) wait on it.
     */
    private boolean basesLoaded(Entry entry) {
        if (entry.bases != null) return true;
        if (entry.basesLoading) return false;
        entry.basesLoading = true;
        UUID id = entry.data.id();
        memories.loadBases(id, entry.data.displayName()).whenComplete((loaded, failure) -> handBack(() -> {
            if (!running || entries.get(id) != entry) return;
            entry.bases = loaded != null ? loaded : new PlayerMemoryStore.Bases();
            // A record it cannot read as one of its stages (an edited file, a stage since renamed) is left out.
            entry.bases.built.removeIf(base -> base == null || base.dimension() == null || stageNamed(base.stage()) == null
                    || base.wood() != null && !dev.kindred.core.construction.Woods.known(base.wood())
                    || base.variant() < 0 || base.variant() > dev.kindred.core.construction.BuildStyle.VARIANTS);
            // A hall it cannot build again as recorded (an edited file) is left out, as a base is.
            var hall = entry.bases.hall;
            if (hall != null && (hall.dimension() == null || hall.wood() == null || !dev.kindred.core.construction.Woods.known(hall.wood())
                    || hall.cells() < dev.kindred.core.construction.TradingHall.MIN_CELLS || hall.cells() > dev.kindred.core.construction.TradingHall.MAX_CELLS)) {
                entry.bases.hall = null;
            }
            if (entry.seedBlock != null) entry.bases.seed = entry.seedBlock;
            // Its bases' designs reserved as its own, as recorded (E-30).
            for (var base : entry.bases.built) {
                designs.reserve(id, entry.data.displayName() + "'s " + base.stage(), dev.kindred.core.construction.DesignFingerprint.of(planOf(base)));
            }
            entry.basesLoading = false;
        }));
        return false;
    }

    /**
     * The first of {@code grown}'s variants on whose plan is no near copy of a design another player has reserved
     * (E-30), reserved as its own: two players' bases are not one design, turned or in other wood or with a window more.
     */
    private dev.kindred.core.construction.BuildStyle unique(Entry entry, dev.kindred.core.construction.Houses.Stage stage,
                                                            dev.kindred.core.construction.BuildStyle grown) {
        String copied = null;
        for (int k = 0; k < dev.kindred.core.construction.BuildStyle.VARIANTS; k++) {
            int variant = 1 + Math.floorMod(grown.variant() - 1 + k, dev.kindred.core.construction.BuildStyle.VARIANTS);
            var style = new dev.kindred.core.construction.BuildStyle(grown.seed(), grown.wood(), grown.stone(), variant, grown.turns());
            var refused = designs.reserve(entry.data.id(), entry.data.displayName() + "'s " + stage.noun,
                    dev.kindred.core.construction.DesignFingerprint.of(dev.kindred.core.construction.Houses.of(stage, style)));
            if (refused.isEmpty()) {
                if (copied != null) KindredMod.LOGGER.info("{}'s {}: its plan {} would copy {}; plan {} instead", entry.data.displayName(), stage.noun,
                        grown.variant(), copied, variant);
                return style;
            }
            if (copied == null) copied = refused.get().name();
        }
        return grown;
    }

    private boolean startBase(Entry entry, PlayerMemoryStore.Base base, String why) {
        var style = styleOf(base);
        if (startBuild(server.getCommandSource(), entry.data.id(), planOf(base), new BlockPos(base.x(), base.y(), base.z()), style.turns()) != 1) {
            return false;
        }
        entry.baseBuild = entry.build;
        var span = footprint(base);
        say(entry, why + ": a " + style.wood().replace('_', ' ') + " " + base.stage() + ".", "at " + span.minX() + ", " + base.y() + ", " + span.minZ());
        return true;
    }

    /** The cells of the trading hall a player builds of its own accord (E-45d). */
    static final int HALL_CELLS = 3;

    private boolean startHall(Entry entry, PlayerMemoryStore.Hall hall, String why) {
        var plan = hallPlan(hall);
        if (startBuild(server.getCommandSource(), entry.data.id(), plan, new BlockPos(hall.x(), hall.y(), hall.z()), 0) != 1) return false;
        entry.hallBuild = entry.build;
        noteBase(entry, why);
        say(entry, why + ": a trading hall of " + hall.cells() + " cells.", "at " + hall.x() + ", " + hall.y() + ", " + hall.z());
        return true;
    }

    /** Its trading hall's build has ended: whole, or after its last try as far as it goes, it stands. */
    private void hallBuilt(Entry entry, BuildRunner build) {
        entry.hallBuild = null;
        if (entry.hallRepair) {
            // A repair that ends short is tried again later, never at once: what it lacks may come with time.
            entry.hallRepair = false;
            if (!build.complete()) entry.baseCheckAt = server.getTicks() + BASE_RETRY;
            noteBase(entry, build.complete() ? "Its trading hall is whole again" : "Its trading hall's repair ended short (" + build.progress() + "); back to it later");
            return;
        }
        var record = entry.bases;
        if (record == null || record.hall == null) return;
        if (!build.complete() && ++entry.hallTries < BASE_TRIES) {
            entry.baseCheckAt = server.getTicks() + BASE_RETRY;
            noteBase(entry, "Its trading hall ended short (" + build.progress() + "); back to it later");
            return;
        }
        entry.hallTries = 0;
        record.hall = record.hall.finished();
        memories.saveBases(entry.data.id(), record);
        noteBase(entry, "Its trading hall stands" + (build.complete() ? "" : " as far as it goes (" + build.progress() + ")"));
    }

    /**
     * Whether it keeps a villager worth a cell of its own (E-45c's whom to keep): a librarian it rerolled and kept, or a
     * villager it has looked at whose offers are worth keeping to it as it stands.
     */
    private boolean keepsAVillager(Entry entry, NativePlayerBody body) {
        if (!entry.rerollKept.isEmpty()) return true;
        if (entry.villagers.isEmpty()) return false;
        var holding = Valuables.holding(body.entity(), lootWanted(entry));
        for (var villager : entry.villagers.values()) {
            if (dev.kindred.core.guide.Trades.worthKeeping(villager.offers(), holding)) return true;
        }
        return false;
    }

    /** The ground a trading hall covers. */
    private static dev.kindred.core.construction.BaseSite.Footprint footprint(PlayerMemoryStore.Hall hall) {
        return new dev.kindred.core.construction.BaseSite.Footprint(hall.x(), hall.z(),
                hall.x() + dev.kindred.core.construction.TradingHall.width(hall.cells()) - 1, hall.z() + dev.kindred.core.construction.TradingHall.DEPTH - 1);
    }

    /** The player's trading hall (E-45d), for fixtures. */
    Optional<PlayerMemoryStore.Hall> hall(UUID id) {
        requireThread();
        Entry entry = id != null ? entries.get(id) : null;
        return entry == null || entry.bases == null ? Optional.empty() : Optional.ofNullable(entry.bases.hall);
    }

    /** The style a base was built in: its own, or for a base recorded before E-29a the first plan in oak. */
    private static dev.kindred.core.construction.BuildStyle styleOf(PlayerMemoryStore.Base base) {
        if (base.wood() == null) return dev.kindred.core.construction.BuildStyle.CLASSIC;
        return new dev.kindred.core.construction.BuildStyle(base.seed(), base.wood(), "cobblestone", base.variant(), base.turns());
    }

    /** A base's plan, in its own style. */
    private static dev.kindred.core.construction.Blueprint planOf(PlayerMemoryStore.Base base) {
        return dev.kindred.core.construction.Houses.of(stageOf(base), styleOf(base));
    }

    /** A base's blocks as the world holds them: its plan turned and placed at its origin. */
    private static List<dev.kindred.core.construction.Blueprint.Block> placedOf(PlayerMemoryStore.Base base) {
        return planOf(base).placed(new dev.kindred.core.construction.Pos(base.x(), base.y(), base.z()), styleOf(base).turns());
    }

    /** The ground a base covers. */
    private static dev.kindred.core.construction.BaseSite.Footprint footprint(PlayerMemoryStore.Base base) {
        int minX = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;
        for (var block : placedOf(base)) {
            minX = Math.min(minX, block.at().x());
            minZ = Math.min(minZ, block.at().z());
            maxX = Math.max(maxX, block.at().x());
            maxZ = Math.max(maxZ, block.at().z());
        }
        return new dev.kindred.core.construction.BaseSite.Footprint(minX, minZ, maxX, maxZ);
    }

    /**
     * The wood a player has to hand for a base grown with no seed block (E-29a): the wood it carries most of, as
     * planks or logs, else that of the nearest tree it knows, else none.
     */
    private static String woodAtHand(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var count = new HashMap<String, Integer>();
        var inventory = player.getInventory();
        for (int slot = 0; slot < inventory.size(); slot++) {
            var stack = inventory.getStack(slot);
            String id = Registries.ITEM.getId(stack.getItem()).getPath();
            String wood = id.endsWith("_planks") || id.endsWith("_log") ? dev.kindred.core.construction.BuildStyle.woodOf(id) : null;
            boolean log = id.endsWith("_log");
            if (wood == null && !stack.isEmpty()) {
                // F-38: a wood the server's tags and recipes name, whatever its ids are called.
                String full = Registries.ITEM.getId(stack.getItem()).toString();
                var facts = dev.kindred.core.Capabilities.current();
                log = facts.is(dev.kindred.core.VanillaIds.LOGS, full);
                if (log || facts.is(dev.kindred.core.VanillaIds.PLANKS, full)) {
                    wood = facts.woodOfPart(full).map(dev.kindred.core.Capabilities.Wood::name).orElse(null);
                }
            }
            if (wood != null) count.merge(wood, stack.getCount() * (log ? 4 : 1), Integer::sum);
        }
        var held = count.entrySet().stream().max(Map.Entry.comparingByValue()).map(Map.Entry::getKey);
        if (held.isPresent()) return held.get();
        if (entry.campaign == null) return null;
        var world = player.getServerWorld();
        return entry.campaign.knowledge().nearest(world, WorldKnowledge.Kind.LOG, player.getBlockPos(), p -> true)
                .map(p -> dev.kindred.core.construction.BuildStyle.woodOf(Registries.BLOCK.getId(world.getBlockState(p).getBlock()).getPath()))
                .orElse(null);
    }

    /**
     * The seed block a player grows its builds from (E-29a), as given: a block it builds round, its wood for the
     * walls' trim if it is wood. It takes effect for the next stage it builds. Null clears it.
     */
    int setSeedBlock(ServerCommandSource source, UUID id, String block) {
        requireThread();
        if (id == null) id = defaultBotId();
        Entry entry = id != null ? entries.get(id) : null;
        if (entry == null || entry.nativeState == null || !nativeMayControl(source, entry)) {
            return reject(source, "Native player unavailable or administrative access denied.");
        }
        String seed = null;
        if (block != null) {
            var parsed = Identifier.tryParse(block.contains(":") ? block : "minecraft:" + block);
            if (parsed == null || !Registries.BLOCK.containsId(parsed)) return reject(source, "No such block: " + block);
            seed = parsed.toString();
        }
        entry.seedBlock = seed;
        if (entry.bases != null) {
            entry.bases.seed = seed;
            memories.saveBases(entry.data.id(), entry.bases);
        }
        String wood = dev.kindred.core.construction.BuildStyle.woodOf(seed);
        feedback(source, seed == null ? entry.data.displayName() + " grows its builds from the wood it has to hand."
                : entry.data.displayName() + " grows its next builds from " + seed + (wood == null ? ", in the wood it has to hand." : ", in " + wood.replace('_', ' ') + "."));
        return 1;
    }

    /** A fixture's hook: every base this player begins from now on is built in {@code style}, not grown. */
    void fixBaseStyle(UUID id, dev.kindred.core.construction.BuildStyle style) {
        requireThread();
        Entry entry = entries.get(id);
        if (entry != null) entry.fixedBaseStyle = style;
    }

    /** A base's build has ended: whole, or after its last try as far as it goes, it is the player's base now. */
    private void baseBuilt(Entry entry, BuildRunner build) {
        entry.baseBuild = null;
        var repaired = entry.baseRepair;
        entry.baseRepair = null;
        if (repaired != null) {
            // A repair that ends short is tried again later, never at once: what it lacks may come with time.
            if (!build.complete()) entry.baseCheckAt = server.getTicks() + BASE_RETRY;
            noteBase(entry, build.complete() ? "Its " + repaired.stage() + " is whole again"
                    : "Its " + repaired.stage() + "'s repair ended short (" + build.progress() + "); back to it later");
            return;
        }
        var record = entry.bases;
        if (record == null || record.built.isEmpty()) return;
        int at = record.built.size() - 1;
        var last = record.built.get(at);
        if (!build.complete() && ++entry.baseTries < BASE_TRIES) {
            entry.baseCheckAt = server.getTicks() + BASE_RETRY;
            noteBase(entry, "Its " + last.stage() + " ended short (" + build.progress() + "); back to it later");
            return;
        }
        entry.baseTries = 0;
        // As far as it goes, it is its base now; what it still lacks is a repair, tried later rather than at once.
        if (!build.complete()) entry.baseCheckAt = server.getTicks() + BASE_RETRY;
        record.built.set(at, last.finished());
        memories.saveBases(entry.data.id(), record);
        noteBase(entry, "Its " + last.stage() + " stands" + (build.complete() ? "" : " as far as it goes (" + build.progress() + ")"));
    }

    private static final int FOOD_LOOKS = 3, FOOD_RETRY = 6000, SLEEP_RETRY = 600, BED_REACH = 96;

    /**
     * Life comes first for it (F-25c9): no running goal, and work of its own (a ranch, a field, a build or its base); or a
     * faction world, goal or not (M-06i), where the faction world's choices come before goal steps and so must not come
     * before its bed at night and food when hunger is low.
     */
    private boolean lifeFirst(Entry entry) {
        if (factionsWorld()) return true;
        return goalOf(entry) == dev.kindred.core.survival.SurvivalGoal.NONE
                && (entry.ranch != null || entry.field != null || entry.build != null || bases && worldEditsEnabled());
    }

    /**
     * What keeps the player alive, ahead of its ranch, build or base (F-25c9), as {@link dev.kindred.core.survival.LifeFirst}
     * weighs it: at night, to a bed of its own and to sleep there, which sets its spawn; when hunger is low, food until
     * it has enough to last, hunted as the goal hunts and looked for a few walks out before it gives up for a while.
     * Empty when nothing comes before its work.
     */
    private List<NativeTaskCandidate> lifeCandidates(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var world = player.getServerWorld();
        long now = server.getTicks();
        long time = world.getTimeOfDay() % 24000L;
        boolean sleepTime = world.isNight() || world.isThundering() || time >= 12542L && time <= 23460L;
        // Dug in for the night by its goal (a faction world's life first beside a goal, M-06i): the goal's shelter is its
        // night, and no walk to a bed takes it out of it.
        boolean dugIn = goalOf(entry) != dev.kindred.core.survival.SurvivalGoal.NONE && entry.campaign != null && entry.campaign.dugInForTheNight(player);
        BlockPos bed = player.isSleeping() ? player.getSleepingPosition().orElse(null)
                : sleepTime && !dugIn && now >= entry.sleepRetryAt ? nearestOwnBed(entry, world, player.getBlockPos()) : null;
        int hunger = player.getHungerManager().getFoodLevel();
        int carried = foodCarried(player);
        var decision = dev.kindred.core.survival.LifeFirst.next(new dev.kindred.core.survival.LifeFirst.State(hunger, carried, sleepTime,
                bed != null, entry.gettingFood, now < entry.foodSoughtUntil));
        if (decision.need().isEmpty()) {
            if (entry.gettingFood) {
                entry.gettingFood = false;
                entry.foodLooks = 0;
                noteLife(entry, "Food enough to last: " + (hunger + carried) + " in its body and its pack");
            }
            return List.of();
        }
        noteLife(entry, decision.why());
        PortalRunCampaign.Task task;
        if (decision.need().get() == dev.kindred.core.survival.LifeFirst.Need.SLEEP) {
            if (player.isSleeping()) task = new PortalRunCampaign.Task("native_wait", Map.of("seconds", "1"), "Asleep in its bed");
            else if (player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(bed)) > 3.5 * 3.5) task = PortalRunCampaign.go(bed, 2.0, false, "To its bed for the night");
            else task = new PortalRunCampaign.Task("native_sleep", Map.of("x", String.valueOf(bed.getX()), "y", String.valueOf(bed.getY()),
                    "z", String.valueOf(bed.getZ())), "Sleep in its own bed");
        } else {
            entry.gettingFood = true;
            // What it put by in its own storage first (F-25c9b): bread in its chest is eaten before a cow is hunted.
            var stored = storedFood(entry, player, hunger + carried);
            if (stored.isPresent()) {
                task = stored.get();
            } else {
                if (entry.campaign == null) entry.campaign = new PortalRunCampaign();
                entry.campaign.policy(edits);
                // Never the kind of animal its ranch is penning: those are its pair to breed.
                var ranch = entry.ranch;
                var found = entry.campaign.huntFood(body, animal -> ranch != null && dev.kindred.core.survival.Ranch.Kind.of(
                        net.minecraft.registry.Registries.ENTITY_TYPE.getId(animal.getType()).toString()).filter(k -> k == ranch.ranch.kind()).isPresent());
                // No animal in sight: fish at water close by with a rod it holds, before it walks out to look (E-05).
                if (found.isEmpty()) found = entry.campaign.fish(body);
                if (found.isEmpty() && entry.foodLooks < FOOD_LOOKS) found = entry.campaign.lookFor(body, "food");
                if (found.isEmpty()) {
                    entry.gettingFood = false;
                    entry.foodLooks = 0;
                    entry.foodSoughtUntil = now + FOOD_RETRY;
                    noteLife(entry, "No food to be had about here for now: back to its work, and it looks again later");
                    return List.of();
                }
                task = found.get();
            }
        }
        UUID id = UUID.nameUUIDFromBytes(("life:" + entry.data.id() + ":" + task.skill() + ":" + new java.util.TreeMap<>(task.args()))
                .getBytes(StandardCharsets.UTF_8));
        entry.lifeTaskId = id;
        entry.lifeTask = task;
        // Its hunt is the goal's own, so the goal's record of how its steps went keeps it from the same dead end again.
        if (decision.need().get() == dev.kindred.core.survival.LifeFirst.Need.FOOD && !task.label().endsWith(FROM_STORAGE)) {
            entry.campaignTasks.clear();
            entry.campaignTasks.put(id, task);
        }
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.PROJECT, decision.weight(),
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(candidate, task.skill(), task.args()));
    }

    private static final String FROM_STORAGE = "from its storage";

    /**
     * Its night (E-70a), as {@link dev.kindred.core.survival.Nights} decides it: home by dusk, turned for home in time to be
     * in its own bed when sleeping first becomes possible, and asleep there; and to bed when a person in the Overworld
     * lies down, if it can be, so that person's night is not held up. On its way to bed with a person asleep, it counts
     * toward that person's night ({@link SleepCount}) for a bounded time. Null when nothing about the night comes first
     * (the day, no bed of its own in reach, a match keeping its own rules, the Nether or the End): the rest of its
     * choices, a goal's own night among them, go on as before.
     */
    private List<NativeTaskCandidate> nightCandidates(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var world = player.getServerWorld();
        long now = server.getTicks();
        if (!nightsOn) return null;
        boolean overworld = world.getRegistryKey() == net.minecraft.world.World.OVERWORLD;
        boolean ownRules = ownNightRules(entry);
        boolean goal = goalOf(entry) != dev.kindred.core.survival.SurvivalGoal.NONE;
        // A goal's player below ground is mid-task, and its goal keeps its night there (dug in, or mining on).
        boolean below = goal && PortalRunCampaign.underground(player);
        BlockPos bed = player.isSleeping() ? player.getSleepingPosition().orElse(null)
                : overworld && !below && now >= entry.sleepRetryAt ? homeBed(entry, world, player) : null;
        double toBed = bed == null ? -1 : Math.sqrt(player.getBlockPos().getSquaredDistance(bed));
        entry.homeInReach = dev.kindred.core.survival.Nights.turnForHomeAt(toBed, 0) >= 0;
        boolean carries = player.getInventory().containsAny(stack -> stack.isIn(net.minecraft.registry.tag.ItemTags.BEDS));
        boolean fighting = player.hurtTime > 0 || player.getAttacker() != null
                || !world.getEntitiesByClass(net.minecraft.entity.mob.HostileEntity.class, player.getBoundingBox().expand(12, 6, 12),
                        mob -> mob.isAlive() && mob.getTarget() == player).isEmpty();
        boolean personAsleep = overworld && world.getPlayers().stream().anyMatch(p -> !(p instanceof PreparedNativePlayer) && p.isSleeping());
        var decision = dev.kindred.core.survival.Nights.decide(new dev.kindred.core.survival.Nights.State(world.getTimeOfDay(), world.isThundering(),
                overworld, ownRules, toBed, 0, carries, entry.campaign != null && goal && entry.campaign.nightWork(player), personAsleep, !fighting && !below));
        boolean home = decision.plan() == dev.kindred.core.survival.Nights.Plan.HOME && bed != null && !fighting;
        if (entry.campaign != null) entry.campaign.nights(!ownRules, entry.homeInReach);
        // On its way to bed while a person sleeps, it counts toward their night, from the moment it set off and for a
        // bounded while: a person's night is never held for longer.
        if (home && personAsleep && !player.isSleeping()) {
            if (entry.toBedSince < 0) entry.toBedSince = now;
            SleepCount.toBed(server, player.getUuid(), entry.toBedSince + dev.kindred.core.survival.Nights.TO_BED_LIMIT);
        } else {
            entry.toBedSince = -1;
            SleepCount.toBed(server, player.getUuid(), -1);
        }
        PortalRunCampaign.Task task = null;
        double weight = decision.weight();
        if (!home && !goal && !fighting) {
            // Without a goal or work of its own, the bed it carries for a night with home out of reach, and taken back up in
            // the morning, as a goal's player does on its way (E-70a). A player with work of its own (a build, its base, a
            // ranch or a field) keeps the night life-first gives it (F-25c9): the bed in its pack is the one its build sets
            // down, and dug in beside its build it would build nothing (the house fixtures on #216's head).
            boolean ownWork = entry.ranch != null || entry.field != null || entry.build != null || bases && worldEditsEnabled();
            boolean carried = !ownWork && decision.plan() == dev.kindred.core.survival.Nights.Plan.CARRIED
                    || entry.campaign != null && entry.campaign.carriedBed(world) != null;
            if (carried) {
                if (entry.campaign == null) entry.campaign = new PortalRunCampaign();
                entry.campaign.policy(edits);
                entry.campaign.nights(true, false);
                task = entry.campaign.carriedBedNight(body).orElse(null);
                if (decision.plan() != dev.kindred.core.survival.Nights.Plan.CARRIED) weight = dev.kindred.core.survival.Nights.BED;
            }
            // Home again by day after a night away: its home bed used, which sets where it wakes after a death back there.
            if (task == null && overworld && !ownRules) task = homeAgain(entry, world, player);
            if (task == null) return null;
            if (decision.plan() == dev.kindred.core.survival.Nights.Plan.NONE) weight = HOME_AGAIN_WEIGHT;
        } else if (!home) {
            return null;
        }
        noteLife(entry, task != null ? task.label() : decision.why());
        // Unless the carried bed's night or morning, or home's bed set again, was chosen above: its own bed.
        if (task == null) task = toOwnBed(player, world, bed, personAsleep);
        UUID id = UUID.nameUUIDFromBytes(("night:" + entry.data.id() + ":" + task.skill() + ":" + new java.util.TreeMap<>(task.args()))
                .getBytes(StandardCharsets.UTF_8));
        entry.lifeTaskId = id;
        entry.lifeTask = task;
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.PROJECT, weight,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(candidate, task.skill(), task.args()));
    }

    /** To its own bed at {@code bed} and asleep there, lying down the moment a bed can be slept in (E-70a). */
    private static PortalRunCampaign.Task toOwnBed(ServerPlayerEntity player, ServerWorld world, BlockPos bed, boolean personAsleep) {
        if (player.isSleeping()) return new PortalRunCampaign.Task("native_wait", Map.of("seconds", "1"), "Asleep in its bed");
        if (player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(bed)) > 3.5 * 3.5) {
            return PortalRunCampaign.go(bed, 2.0, false, personAsleep ? "To its bed: a person is going to bed" : "To its bed for the night");
        }
        long time = world.getTimeOfDay() % 24000L;
        if (!dev.kindred.core.survival.Nights.sleepTime(time, world.isThundering())) {
            // By its bed before a bed can be slept in: it waits there.
            long seconds = Math.clamp((dev.kindred.core.survival.Nights.SLEEP_FROM - time + 19) / 20, 1, 5);
            return new PortalRunCampaign.Task("native_wait", Map.of("seconds", String.valueOf(seconds)), "By its bed till it can sleep");
        }
        return new PortalRunCampaign.Task("native_sleep", Map.of("x", String.valueOf(bed.getX()), "y", String.valueOf(bed.getY()),
                "z", String.valueOf(bed.getZ())), "Sleep in its own bed");
    }

    /** The weight of setting its home bed again on coming home by day: above its work, below its night. */
    private static final double HOME_AGAIN_WEIGHT = 76;

    /** A match it is in, or its playstyle, keeps its own rules for the night (a speedrun, a manhunt), or it only watches. */
    private boolean ownNightRules(Entry entry) {
        return worldMode == dev.kindred.core.match.GameModes.WorldMode.SPEEDRUN || worldMode == dev.kindred.core.match.GameModes.WorldMode.MANHUNT
                || entry.runtimeSettings.playstyleProfile() == PlaystyleProfile.SPEEDRUN_ANY_PERCENT
                || entry.runtimeSettings.playstyleProfile().isIdleObserving();
    }

    /**
     * Its home bed in this world (E-70a): the nearest free bed of its own bases; or else the bed it slept in at home,
     * remembered; or else the bed it last slept in, where it wakes after a death (its spawn), unless that is the bed it
     * carries. Each only if it still stands and no one is in it. Null when it has none.
     */
    private static BlockPos homeBed(Entry entry, ServerWorld world, ServerPlayerEntity player) {
        BlockPos own = nearestOwnBed(entry, world, player.getBlockPos());
        if (own != null) return own;
        String dimension = world.getRegistryKey().getValue().toString();
        if (entry.homeBed != null && dimension.equals(entry.homeBedWorld) && freeBed(world, entry.homeBed)) return entry.homeBed;
        BlockPos spawn = spawnBed(world, player);
        if (spawn == null || entry.campaign != null && spawn.equals(entry.campaign.carriedBed(world)) || !freeBed(world, spawn)) return null;
        entry.homeBed = spawn;
        entry.homeBedWorld = dimension;
        return spawn;
    }

    /** A bed's head at {@code at}, loaded, standing and free. */
    private static boolean freeBed(ServerWorld world, BlockPos at) {
        if (!world.isChunkLoaded(at)) return false;
        var state = world.getBlockState(at);
        return state.isIn(BlockTags.BEDS) && !state.get(net.minecraft.block.BedBlock.OCCUPIED);
    }

    /**
     * Home again by day after a night away (E-70a): within a short walk of its home bed while it wakes somewhere else
     * after a death, it uses that bed, which sets where it wakes back at home, as a person does on coming home. Null
     * when there is nothing to set.
     */
    private PortalRunCampaign.Task homeAgain(Entry entry, ServerWorld world, ServerPlayerEntity player) {
        if (entry.homeBed == null || !world.getRegistryKey().getValue().toString().equals(entry.homeBedWorld)) return null;
        if (server.getTicks() < entry.sleepRetryAt || !freeBed(world, entry.homeBed)) return null;
        if (entry.homeBed.equals(spawnBed(world, player))) return null;
        if (entry.campaign != null && entry.campaign.carriedBed(world) != null) return null; // Its own bed still to take up first.
        if (player.getBlockPos().getSquaredDistance(entry.homeBed) > HOME_AGAIN_REACH * HOME_AGAIN_REACH) return null;
        BlockPos bed = entry.homeBed;
        if (player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(bed)) > 3.5 * 3.5) return PortalRunCampaign.go(bed, 2.0, false, "To its bed: home again");
        return new PortalRunCampaign.Task("native_sleep", Map.of("x", String.valueOf(bed.getX()), "y", String.valueOf(bed.getY()),
                "z", String.valueOf(bed.getZ()), "anchor", "true"), "Its home bed set again: home after a night away");
    }

    /** How near its home bed it comes before it sets it again by day. */
    private static final int HOME_AGAIN_REACH = 24;

    /** The head of the bed its spawn is set at in this world, or null (its spawn elsewhere, or not at a bed). */
    private static BlockPos spawnBed(ServerWorld world, ServerPlayerEntity player) {
        BlockPos at = player.getSpawnPointPosition();
        if (at == null || player.getSpawnPointDimension() != world.getRegistryKey() || !world.isChunkLoaded(at)) return null;
        var state = world.getBlockState(at);
        if (!state.isIn(BlockTags.BEDS)) return null;
        return state.get(net.minecraft.block.BedBlock.PART) == net.minecraft.block.enums.BedPart.HEAD ? at
                : at.offset(state.get(net.minecraft.block.BedBlock.FACING));
    }

    /**
     * Food in its own storage, taken before it hunts (F-25c9b): to its storage when it is out of reach, then the most
     * filling safe food there, as much as brings it to enough to last ({@code has} is what it has in its body and pack).
     * Empty when it has no storage near, or none of the food there is safe to eat.
     */
    private java.util.Optional<PortalRunCampaign.Task> storedFood(Entry entry, ServerPlayerEntity player, int has) {
        if (entry.setup == null || entry.setup.storage() == null) return java.util.Optional.empty();
        var at = entry.setup.storage().position();
        BlockPos storage = new BlockPos(at.x(), at.y(), at.z());
        var world = player.getServerWorld();
        if (!world.getRegistryKey().getValue().toString().equals(entry.setup.dimension()) || !world.isChunkLoaded(storage)
                || player.getBlockPos().getSquaredDistance(storage) > BED_REACH * BED_REACH
                || !(world.getBlockEntity(storage) instanceof net.minecraft.inventory.Inventory chest)) return java.util.Optional.empty();
        ItemStack best = null;
        for (int slot = 0; slot < chest.size(); slot++) {
            var stack = chest.getStack(slot);
            if (isEligibleFood(stack, true, false) && (best == null
                    || stack.get(DataComponentTypes.FOOD).nutrition() > best.get(DataComponentTypes.FOOD).nutrition())) best = stack;
        }
        if (best == null) return java.util.Optional.empty();
        String name = best.getName().getString().toLowerCase(java.util.Locale.ROOT);
        if (player.getEyePos().squaredDistanceTo(Vec3d.ofCenter(storage)) > 4.2 * 4.2) {
            return java.util.Optional.of(PortalRunCampaign.go(storage, 2.5, false, "To its storage for " + name));
        }
        int each = best.get(DataComponentTypes.FOOD).nutrition(), held = 0;
        for (int slot = 0; slot < chest.size(); slot++) if (chest.getStack(slot).isOf(best.getItem())) held += chest.getStack(slot).getCount();
        int short_ = dev.kindred.core.survival.LifeFirst.FULL + dev.kindred.core.survival.LifeFirst.RESERVE - has;
        int count = Math.min(held, Math.max(1, (short_ + each - 1) / each));
        return java.util.Optional.of(new PortalRunCampaign.Task("native_take", Map.of("item",
                net.minecraft.registry.Registries.ITEM.getId(best.getItem()).toString(), "count", String.valueOf(count)),
                "Take " + count + " " + name + " " + FROM_STORAGE));
    }

    /** The food points of the safe food it carries, as it would eat it. */
    private static int foodCarried(ServerPlayerEntity player) {
        int points = 0;
        var inventory = player.getInventory();
        for (int slot = 0; slot < inventory.size(); slot++) {
            var stack = inventory.getStack(slot);
            if (!isEligibleFood(stack, true, false)) continue;
            points += stack.get(DataComponentTypes.FOOD).nutrition() * stack.getCount();
        }
        return points;
    }

    /** The nearest bed of its own bases in this world, free and within a walk of {@code from}, or null (F-25c9). */
    private static BlockPos nearestOwnBed(Entry entry, ServerWorld world, BlockPos from) {
        BlockPos best = null;
        for (BlockPos bed : ownBeds(entry, world)) {
            if (!world.isChunkLoaded(bed)) continue;
            var state = world.getBlockState(bed);
            if (!state.isIn(BlockTags.BEDS) || state.get(net.minecraft.block.BedBlock.OCCUPIED)) continue;
            double d = bed.getSquaredDistance(from);
            if (d > BED_REACH * BED_REACH) continue;
            if (best == null || d < best.getSquaredDistance(from)) best = bed;
        }
        return best;
    }

    /** Whether {@code at} is either half of a bed of its own bases. */
    private static boolean ownBed(Entry entry, ServerWorld world, BlockPos at) {
        var state = world.getBlockState(at);
        if (!state.isIn(BlockTags.BEDS)) return false;
        BlockPos head = state.get(net.minecraft.block.BedBlock.PART) == net.minecraft.block.enums.BedPart.HEAD ? at
                : at.offset(state.get(net.minecraft.block.BedBlock.FACING));
        // Its home bed, and the bed it last slept in, where it wakes after a death, are its own too (E-70a).
        if (head.equals(entry.homeBed) || entry.nativeBody != null && head.equals(spawnBed(world, entry.nativeBody.entity()))) return true;
        return ownBeds(entry, world).contains(head);
    }

    /** Where the heads of the beds of its bases in this world stand, by their plans. */
    private static List<BlockPos> ownBeds(Entry entry, ServerWorld world) {
        if (entry.bases == null) return List.of();
        String dimension = world.getRegistryKey().getValue().toString();
        var beds = new java.util.ArrayList<BlockPos>();
        for (var base : entry.bases.built) {
            if (!base.dimension().equals(dimension)) continue;
            for (var block : placedOf(base)) {
                if (block.spec().block().endsWith("_bed") && "head".equals(block.spec().property("part"))) beds.add(BuildRunner.blockPos(block.at()));
            }
        }
        return beds;
    }

