    /**
     * The duel a player in a running match fights (M-00a): its opponent, with the weapon that deals the most over the
     * fight, or a walk toward it when it is far. Null when the player is in no running match.
     */
    private List<NativeTaskCandidate> duelCandidates(NativePlayerBody body) {
        var player = body.entity();
        var match = matches.running(player.getUuid()).filter(m -> m.mode() == dev.kindred.core.match.MatchRegistry.Mode.DUEL).orElse(null);
        if (match == null) return null;
        var candidates = new java.util.ArrayList<NativeTaskCandidate>();
        UUID opponentId = dev.kindred.core.match.MatchRegistry.other(match, player.getUuid());
        var opponent = opponentId == null ? null : server.getPlayerManager().getPlayer(opponentId);
        if (opponent == null || !opponent.isAlive() || opponent.getServerWorld() != player.getServerWorld()) return candidates;
        UUID taskId = UUID.nameUUIDFromBytes(("duel:" + match.id() + ":" + player.getUuid()).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(taskId, dev.kindred.core.TaskPreferences.Priority.URGENT, 99.0,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        if (player.squaredDistanceTo(opponent) > 20 * 20) {
            BlockPos at = opponent.getBlockPos();
            candidates.add(new NativeTaskCandidate(candidate, "native_goto", Map.of("x", String.valueOf(at.getX()), "y", String.valueOf(at.getY()),
                    "z", String.valueOf(at.getZ()))));
            return candidates;
        }
        Entry self = entryForPlayer(player.getUuid());
        // A declared opponent that stands, for the mechanics suite.
        if (self != null && "idle".equals(self.meleeStyle)) return candidates;
        int slot = Weapons.choose(player, NativePlayerBody.believedHealth(player, opponent), true).map(Weapons.Held::slot).orElse(-1);
        // Its melee's tactics (E-41b), on but for a declared baseline in a benchmark.
        var args = new HashMap<String, String>(Map.of("target", opponentId.toString(), "slot", String.valueOf(slot)));
        if (self != null && !self.meleeTactics) args.put("tactics", "false");
        if (self != null && self.meleeStyle != null) {
            args.put("tactics", "false");
            args.put("style", self.meleeStyle);
        }
        candidates.add(new NativeTaskCandidate(candidate, "native_fight", Map.copyOf(args)));
        return candidates;
    }

    /** A match's player by name or id: an AI player (its body's player id) or a human online. */
    UUID matchPlayerId(String raw) {
        requireThread();
        UUID bot = resolveBotId(raw);
        if (bot != null) {
            Entry entry = entries.get(bot);
            return entry != null && entry.nativeBody != null && entry.nativeBody.entity() != null ? entry.nativeBody.entity().getUuid() : null;
        }
        var human = server.getPlayerManager().getPlayer(raw);
        return human != null ? human.getUuid() : null;
    }

    /** The entry whose body is player {@code playerId}, if it is a native player here. */
    private Entry entryForPlayer(UUID playerId) {
        for (Entry entry : entries.values()) {
            if (entry.nativeBody != null && entry.nativeBody.entity() != null && entry.nativeBody.entity().getUuid().equals(playerId)) return entry;
        }
        return null;
    }

    private final dev.kindred.core.wire.Wording onlookerWording = new dev.kindred.core.wire.Wording();

    private static List<String> lastOf(List<String> lines, int most) {
        return List.copyOf(lines.subList(Math.max(0, lines.size() - most), lines.size()));
    }

    /** What an AI player was told lately on the Wire (F-34c), oldest first, as an onlooker of the watch page or the K panel may read it. */
    private List<String> toldLately(UUID ai) {
        var inbox = wire.inbox(ai);
        var out = new ArrayList<String>();
        for (var t : inbox.subList(Math.max(0, inbox.size() - dev.kindred.core.watch.WatchSnapshot.TOLD), inbox.size())) {
            var m = t.message();
            Entry from = m.fromServer() ? null : entries.get(m.from());
            out.add(onlookerWording.forOnlookers(m, m.fromServer() ? "" : from != null ? from.data.displayName() : playerName(m.from())));
        }
        return out;
    }

    private String playerName(UUID playerId) {
        var player = server.getPlayerManager().getPlayer(playerId);
        return player != null ? player.getName().getString() : playerId.toString().substring(0, 8);
    }

    /** Tells every invited player where its match stands. */
    private void announce(dev.kindred.core.match.MatchRegistry.Match match) {
        boolean race = match.mode() == dev.kindred.core.match.MatchRegistry.Mode.SPEEDRUN;
        String what = switch (match.state()) {
            case LOBBY -> "waiting for every player to join";
            case COUNTDOWN -> "starting in three seconds";
            case RUNNING -> switch (match.mode()) {
                case SPEEDRUN -> "go!";
                case MANHUNT -> "the hunt is on!";
                case BUILDER -> "build!";
                case DUEL -> "fight!";
            };
            case VOTING -> "time is up; vote on each build, one to five (/aiplayer match vote <player> <score>)";
            case ENDED -> match.winner() != null ? playerName(match.winner()) + " wins (" + match.result() + ")" : match.result();
        };
        String line = match.mode().label() + " " + who(match) + ": " + what;
        KindredMod.LOGGER.info(line);
        if (watch != null) highlight(server.getTicks(), "", "match", line);
        presenter.changed(match, this::playerName);
        boolean hunt = match.mode() == dev.kindred.core.match.MatchRegistry.Mode.MANHUNT;
        if ((race || hunt) && match.state() == dev.kindred.core.match.MatchRegistry.State.RUNNING && !races.containsKey(match.id())
                && !hunts.contains(match.id())) startRace(match);
        if (race || hunt) leaveRace(match);
        takeBackCompasses(match);
        if (match.mode() == dev.kindred.core.match.MatchRegistry.Mode.BUILDER) {
            if (match.state() == dev.kindred.core.match.MatchRegistry.State.RUNNING && buildsBegun.add(match.id())) startBuilding(match);
            if (match.state() == dev.kindred.core.match.MatchRegistry.State.VOTING) startVoting(match);
            leaveBuilding(match);
        }
        for (UUID invited : match.invited()) {
            var player = server.getPlayerManager().getPlayer(invited);
            if (player != null) player.sendMessage(Text.literal(line), false);
            // An AI player in it chooses again at once: the fight begins, or what it was doing goes on.
            Entry entry = entryForPlayer(invited);
            if (entry != null) {
                entry.cachedRoutineCandidates = List.of();
                entry.routineRefreshPending = true;
                // The fight is what the administrator entered it for: a hold left by an earlier command gives way.
                if (match.state() == dev.kindred.core.match.MatchRegistry.State.RUNNING) entry.manualHoldUntilTick = Long.MIN_VALUE;
            }
        }
    }

    /** The match {@code player} is in, as its bar reads now, or "" when it is in none. */
    String matchLine(UUID player) {
        requireThread();
        return matches.active(player).map(match -> dev.kindred.core.match.MatchPresentation.bar(match, server.getTicks(), this::playerName,
                raceProgress(match.id())).text()).orElse("");
    }

    /** The world's game mode (M-00), or null where none was chosen. */
    dev.kindred.core.match.GameModes.WorldMode worldMode() { return worldMode; }

    /**
     * The group's pace (M-01e): the furthest of vanilla's story steps any human online has reached, from their own
     * advancement progress (announced to everyone, so nothing hidden), kept when it goes further and saved off the game
     * thread. AI players are not the group whose pace is kept.
     */
    private void pollGroupPace() {
        var loader = server.getAdvancementLoader();
        java.util.Optional<dev.kindred.core.match.GroupPace.Step> furthest = java.util.Optional.ofNullable(groupStep);
        for (var player : server.getPlayerManager().getPlayerList()) {
            if (entryForPlayer(player.getUuid()) != null || player.isSpectator()) continue;
            var done = new java.util.ArrayList<String>();
            for (var step : dev.kindred.core.match.GroupPace.Step.values()) {
                var advancement = loader.get(Identifier.of(step.advancement));
                if (advancement != null && player.getAdvancementTracker().getProgress(advancement).isDone()) done.add(step.advancement);
            }
            furthest = dev.kindred.core.match.GroupPace.further(furthest, dev.kindred.core.match.GroupPace.furthest(done));
        }
        if (furthest.isEmpty() || furthest.get() == groupStep) return;
        groupStep = furthest.get();
        KindredMod.LOGGER.info("Group pace: someone has {}", groupStep.deed);
        Path file = metadataDirectory.resolve("pace.properties");
        String content = "# Kindred group pace (M-01e): the furthest step any human in this world has reached.\nfurthest=" + groupStep.name() + "\n";
        paceSaved = paceSaved.handle((ignored, earlier) -> null).thenRunAsync(() -> {
            try {
                Files.createDirectories(metadataDirectory);
                Files.writeString(file, content, StandardCharsets.UTF_8);
            } catch (IOException failure) {
                throw new CompletionException(failure);
            }
        }).whenComplete((ignored, failure) -> {
            if (failure != null) KindredMod.LOGGER.error("Kindred group pace could not be saved", failure);
        });
    }

    /** The group's furthest step (M-01e), for fixtures and the status line. */
    java.util.Optional<dev.kindred.core.match.GroupPace.Step> groupStep() { return java.util.Optional.ofNullable(groupStep); }

    /**
     * The world's game mode chosen (M-00), operators only, and saved in mode.properties. It is announced to everyone
     * online with its rules, and each AI player's playstyle follows it (the profile it maps onto, not a second setting
     * beside it). From then on only its matches, and duels, may be proposed. A match already proposed or running plays
     * on under its own rules. Factions turns the territory guard on (and the borders once the hub is set); any other mode
     * turns it off. Claims and coins stay in the Record either way.
     */
    int setWorldMode(ServerCommandSource source, dev.kindred.core.match.GameModes.WorldMode mode) {
        requireThread();
        if (!ready || !running) return reject(source, "Kindred is loading saved records.");
        if (!source.hasPermissionLevel(2)) return reject(source, "Only an operator may choose the world's mode.");
        if (!mode.playable) return reject(source, mode.label + " is not playable yet.");
        worldMode = mode;
        for (Entry entry : entries.values()) {
            if (entry.nativeState == null) continue;
            entry.runtimeSettings = entry.runtimeSettings.withPlaystyle(mode.playstyle);
            entry.cachedRoutineCandidates = List.of();
            entry.routineRefreshPending = true;
        }
        if (factionsWorld()) {
            TerritoryGuard.activate(factions);
            factions.applyBorders();
        } else {
            TerritoryGuard.deactivate(factions);
        }
        Path file = metadataDirectory.resolve("mode.properties");
        String content = "# Kindred world mode (M-00): coop, speedrun, manhunt, builder or factions.\nmode=" + mode.key() + "\n";
        // In order: two saves left to run side by side could finish the older last and keep it.
        modeSaved = modeSaved.handle((ignored, earlier) -> null).thenRunAsync(() -> {
            try {
                Files.createDirectories(metadataDirectory);
                Files.writeString(file, content, StandardCharsets.UTF_8);
            } catch (IOException failure) {
                throw new CompletionException(failure);
            }
        }).whenComplete((ignored, failure) -> handBack(() -> {
            if (failure != null) {
                KindredMod.LOGGER.error("Kindred world mode could not be saved", failure);
                reject(source, "The mode applies now but could not be saved; it resets on restart.");
            }
        }));
        feedback(source, "This world now plays " + mode.label + "; AI players play at " + mode.playstyle + ".");
        for (var player : server.getPlayerManager().getPlayerList()) {
            if (entryForPlayer(player.getUuid()) == null) tellRules(player, dev.kindred.core.match.GameModes.rules(mode));
        }
        KindredMod.LOGGER.info("World mode: {}", mode.label);
        return 1;
    }

    /** The world's mode and its rules, or a match mode's, told to whoever asks. */
    int showWorldMode(ServerCommandSource source, String which) {
        requireThread();
        dev.kindred.core.match.GameModes.Rules rules;
        if (which == null) {
            if (worldMode == null) {
                feedback(source, "No world mode is chosen: every match may be proposed. Choose one with /aiplayer mode world coop|speedrun|manhunt|builder.");
                return 1;
            }
            rules = dev.kindred.core.match.GameModes.rules(worldMode);
        } else {
            var mode = dev.kindred.core.match.GameModes.parse(which);
            if (mode.isPresent()) {
                rules = dev.kindred.core.match.GameModes.rules(mode.get());
            } else {
                var match = java.util.Arrays.stream(dev.kindred.core.match.MatchRegistry.Mode.values())
                        .filter(m -> m.name().equalsIgnoreCase(which) || m == dev.kindred.core.match.MatchRegistry.Mode.BUILDER && which.equalsIgnoreCase("build")).findFirst();
                if (match.isEmpty()) return reject(source, "No such mode: coop, speedrun, manhunt, builder, factions, or a match: duel, speedrun, manhunt, build.");
                rules = dev.kindred.core.match.GameModes.rules(match.get());
            }
        }
        feedback(source, rules.title() + (which == null ? " (this world's mode)" : "") + ":");
        for (String line : rules.lines()) feedback(source, " " + line);
        return 1;
    }

    /** A player told a mode's rules in chat: the announcement every rule rests on (D6). */
    private void tellRules(ServerPlayerEntity player, dev.kindred.core.match.GameModes.Rules rules) {
        player.sendMessage(Text.literal(rules.title() + " rules:").formatted(net.minecraft.util.Formatting.GOLD), false);
        for (String line : rules.lines()) player.sendMessage(Text.literal(" " + line).formatted(net.minecraft.util.Formatting.GRAY), false);
    }

    /** A player joining the server is told the world's mode and its rules, where one is chosen. */
    void playerJoined(ServerPlayerEntity player) {
        requireThread();
        // A person's builder hold at its join (M-06k3); an AI player's is restored as its body connects.
        if (ready && running && entryForPlayer(player.getUuid()) == null) restoreHoldOnJoin(player);
        if (!ready || worldMode == null || entryForPlayer(player.getUuid()) != null) return;
        player.sendMessage(Text.literal("This world plays " + worldMode.label + ".").formatted(net.minecraft.util.Formatting.GOLD), false);
        tellRules(player, dev.kindred.core.match.GameModes.rules(worldMode));
    }

    /** Whether a match of {@code mode} may be proposed in this world; refused with the reason if not. */
    private boolean modeAllows(ServerCommandSource source, dev.kindred.core.match.MatchRegistry.Mode mode) {
        if (dev.kindred.core.match.GameModes.allows(worldMode, mode)) return true;
        reject(source, dev.kindred.core.match.GameModes.refusal(worldMode, mode));
        return false;
    }

    /**
     * A duel proposed between two players (M-00a). An AI player is entered by whoever administers it; a human must join
     * it itself (/aiplayer match join), so no human is ever entered into a fight by anyone else (D7).
     */
    int proposeDuel(ServerCommandSource source, UUID first, UUID second) {
        return proposeDuel(source, first, second, Set.of());
    }

    /** As the command, with the AI players that said yes for themselves when asked in chat ({@code chose}, E-52). */
    int proposeDuel(ServerCommandSource source, UUID first, UUID second, Set<UUID> chose) {
        return proposeDuel(source, first, second, chose, 0);
    }

    /** As the command, with the duel's own time in ticks ({@code ticks}, zero for its mode's five minutes). */
    int proposeDuel(ServerCommandSource source, UUID first, UUID second, Set<UUID> chose, int ticks) {
        requireThread();
        if (!modeAllows(source, dev.kindred.core.match.MatchRegistry.Mode.DUEL)) return 0;
        // The server's own rule comes first: with PvP off, no player can hurt another, in a match or not.
        if (!server.isPvpEnabled()) return reject(source, "PvP is off on this server (pvp=false in server.properties); no duel can be fought.");
        var invited = List.of(first, second);
        for (UUID player : invited) {
            Entry entry = entryForPlayer(player);
            if (entry == null && server.getPlayerManager().getPlayer(player) == null) return reject(source, "No such player online.");
            if (entry != null && !nativeMayControl(source, entry) && !chose.contains(entry.data.id())) {
                return reject(source, "Administrative access to " + entry.data.displayName() + " denied.");
            }
        }
        var result = ticks > 0 ? matches.proposeDuel(invited, ticks) : matches.propose(dev.kindred.core.match.MatchRegistry.Mode.DUEL, invited);
        if (!result.accepted()) return reject(source, result.reason());
        var match = enter(result.match().orElseThrow());
        feedback(source, match.mode().label() + " " + dev.kindred.core.match.MatchRegistry.shortId(match.id()) + " proposed: " + who(match)
                + "; " + match.joined().size() + " of " + match.invited().size() + " joined.");
        return 1;
    }

    /**
     * The AI players invited to a new match entered by their administrator, who proposed it; each human invited told how
     * to join. Joining is the human's own choice: a click runs the join as that human, and nothing else enters it (D7).
     */
    private dev.kindred.core.match.MatchRegistry.Match enter(dev.kindred.core.match.MatchRegistry.Match match) {
        for (UUID player : match.invited()) {
            if (entryForPlayer(player) != null) {
                match = matches.join(match.id(), player).match().orElse(match);
                continue;
            }
            var human = server.getPlayerManager().getPlayer(player);
            if (human == null) continue;
            String others = match.invited().stream().filter(other -> !other.equals(player)).map(this::playerName)
                    .collect(java.util.stream.Collectors.joining(", "));
            String what = switch (match.mode()) {
                case DUEL -> "a duel against " + others;
                case SPEEDRUN -> "a speedrun race" + (others.isEmpty() ? "" : " against " + others);
                case MANHUNT -> "a manhunt, as " + (match.runners().contains(player) ? "a runner" : "a hunter") + " (" + who(match)
                        + "); once you join, the other side may attack you";
                case BUILDER -> "a build battle against " + others + "; you build in creative on your own plot, then everyone votes";
            };
            String join = "/aiplayer match join " + dev.kindred.core.match.MatchRegistry.shortId(match.id());
            // The match's rules, announced before anyone joins (D6, D7).
            tellRules(human, dev.kindred.core.match.GameModes.rules(match.mode()));
            human.sendMessage(Text.literal("You are invited to " + what + ". To play in it: ").append(Text.literal("[Join]")
                    .styled(style -> style.withColor(net.minecraft.util.Formatting.GREEN)
                            .withClickEvent(new net.minecraft.text.ClickEvent(net.minecraft.text.ClickEvent.Action.RUN_COMMAND, join))
                            .withHoverEvent(new net.minecraft.text.HoverEvent(net.minecraft.text.HoverEvent.Action.SHOW_TEXT, Text.literal(join))))), false);
        }
        return match;
    }

    /** A match's players as its announcements name them. */
    private String who(dev.kindred.core.match.MatchRegistry.Match match) {
        if (match.mode() == dev.kindred.core.match.MatchRegistry.Mode.MANHUNT) {
            return match.invited().stream().filter(match.runners()::contains).map(this::playerName).collect(java.util.stream.Collectors.joining(", "))
                    + " hunted by " + match.invited().stream().filter(p -> !match.runners().contains(p)).map(this::playerName)
                    .collect(java.util.stream.Collectors.joining(", "));
        }
        return match.invited().stream().map(this::playerName).collect(java.util.stream.Collectors.joining(
                match.mode() == dev.kindred.core.match.MatchRegistry.Mode.DUEL ? " against " : ", "));
    }

    /**
     * A speedrun race proposed for one to eight runners (M-03a): from a fresh start to the dragon, timed by the game's
     * ticks, with splits at vanilla's own advancements. Every runner starts with nothing: an empty inventory and none
     * of the splits' advancements, the same rule for humans and AIs. An AI runner is entered by its administrator and
     * needs the server's leave for AI world edits and the dragon fight; a human joins for itself.
     */
    int proposeSpeedrun(ServerCommandSource source, List<UUID> runners) {
        return proposeSpeedrun(source, runners, Set.of());
    }

    /** As the command, with the AI players that said yes for themselves when asked in chat ({@code chose}, E-52). */
    int proposeSpeedrun(ServerCommandSource source, List<UUID> runners, Set<UUID> chose) {
        requireThread();
        if (!modeAllows(source, dev.kindred.core.match.MatchRegistry.Mode.SPEEDRUN)) return 0;
        for (UUID runner : runners) {
            Entry entry = entryForPlayer(runner);
            var player = server.getPlayerManager().getPlayer(runner);
            if (player == null) return reject(source, "No such player online.");
            if (entry != null) {
                if (!nativeMayControl(source, entry) && !chose.contains(entry.data.id())) {
                    return reject(source, "Administrative access to " + entry.data.displayName() + " denied.");
                }
                if (!worldEditsEnabled()) return reject(source, "AI world edits are disabled on this server; an AI runner needs them (/aiplayer edits on).");
                if (!dragonFight) return reject(source, "The dragon fight is off on this server; an AI runner needs it (/aiplayer dragonfight on).");
            }
            if (!player.getInventory().isEmpty()) return reject(source, playerName(runner) + " is not at a fresh start: it carries items.");
            for (var split : dev.kindred.core.match.SpeedrunSplits.ANY_PERCENT) {
                if (reached(player, split)) return reject(source, playerName(runner) + " is not at a fresh start: it has already reached " + split.label() + ".");
            }
        }
        var result = matches.propose(dev.kindred.core.match.MatchRegistry.Mode.SPEEDRUN, runners);
        if (!result.accepted()) return reject(source, result.reason());
        var match = enter(result.match().orElseThrow());
        feedback(source, "Speedrun " + dev.kindred.core.match.MatchRegistry.shortId(match.id()) + " proposed: " + who(match)
                + "; " + match.joined().size() + " of " + match.invited().size() + " joined.");
        return 1;
    }

    /**
     * A manhunt proposed (M-02a): runners make for the dragon while hunters hunt them, two to eight players in all.
     * Everyone starts with nothing, as in a race. An AI player in it is entered by its administrator and needs the
     * server's leave for AI world edits; an AI runner, the dragon fight's too. A human joins for itself, and only then is
     * it fair game (D7).
     */
    int proposeManhunt(ServerCommandSource source, List<UUID> runners, List<UUID> hunters) {
        return proposeManhunt(source, runners, hunters, 0);
    }

    /**
     * As the command, with the runners' head start ({@code headStartTicks}, zero for none): from the start, the hunters
     * are held where they stand and nobody may strike until it is over, the same for human and AI hunters.
     */
    int proposeManhunt(ServerCommandSource source, List<UUID> runners, List<UUID> hunters, int headStartTicks) {
        requireThread();
        if (!modeAllows(source, dev.kindred.core.match.MatchRegistry.Mode.MANHUNT)) return 0;
        if (!server.isPvpEnabled()) return reject(source, "PvP is off on this server (pvp=false in server.properties); no manhunt can be played.");
        var everyone = new ArrayList<UUID>(runners);
        everyone.addAll(hunters);
        for (UUID player : everyone) {
            Entry entry = entryForPlayer(player);
            var online = server.getPlayerManager().getPlayer(player);
            if (online == null) return reject(source, "No such player online.");
            if (entry != null) {
                if (!nativeMayControl(source, entry)) return reject(source, "Administrative access to " + entry.data.displayName() + " denied.");
                if (!worldEditsEnabled()) return reject(source, "AI world edits are disabled on this server; an AI player in a manhunt needs them (/aiplayer edits on).");
                if (runners.contains(player) && !dragonFight) return reject(source, "The dragon fight is off on this server; an AI runner needs it (/aiplayer dragonfight on).");
            }
            if (!online.getInventory().isEmpty()) return reject(source, playerName(player) + " is not at a fresh start: it carries items.");
        }
        var result = matches.proposeManhunt(runners, hunters, headStartTicks);
        if (!result.accepted()) return reject(source, result.reason());
        var match = enter(result.match().orElseThrow());
        feedback(source, "Manhunt " + dev.kindred.core.match.MatchRegistry.shortId(match.id()) + " proposed: " + who(match)
                + "; " + match.joined().size() + " of " + match.invited().size() + " joined.");
        return 1;
    }

    /**
     * A build battle proposed (M-04a): one plot each, laid out in a row from where the operator stands, for two to eight
     * builders. Each arrives with nothing and leaves with nothing: building is in creative, the only mode where blocks
     * are free, and whatever creative gave is cleared at the end. An AI builder needs the server's leave for AI world
     * edits. Operators only, as the plots are laid on the ground: open ground, level and clear sixteen blocks up.
     */
    int proposeBuildBattle(ServerCommandSource source, List<UUID> builders, int buildTicks, dev.kindred.core.match.BuildBattle.Theme theme) {
        requireThread();
        if (!modeAllows(source, dev.kindred.core.match.MatchRegistry.Mode.BUILDER)) return 0;
        if (!source.hasPermissionLevel(2)) return reject(source, "Only an operator lays out a build battle's plots.");
        for (UUID builder : builders) {
            Entry entry = entryForPlayer(builder);
            var online = server.getPlayerManager().getPlayer(builder);
            if (online == null) return reject(source, "No such player online.");
            if (entry != null) {
                if (!nativeMayControl(source, entry)) return reject(source, "Administrative access to " + entry.data.displayName() + " denied.");
                if (!worldEditsEnabled()) return reject(source, "AI world edits are disabled on this server; an AI builder needs them (/aiplayer edits on).");
            }
            if (!online.getInventory().isEmpty()) return reject(source, playerName(builder) + " must arrive with nothing: it carries items.");
        }
        var world = source.getWorld();
        BlockPos feet = BlockPos.ofFloored(source.getPosition());
        var start = new dev.kindred.core.construction.Pos(feet.getX() + 2, feet.getY() - 1, feet.getZ() + 2);
        var plots = dev.kindred.core.match.BuildBattle.layout(builders, start);
        for (var plot : plots) {
            var o = plot.origin();
            for (int x = 0; x < dev.kindred.core.match.BuildBattle.PLOT; x++) for (int z = 0; z < dev.kindred.core.match.BuildBattle.PLOT; z++) {
                BlockPos floor = new BlockPos(o.x() + x, o.y(), o.z() + z);
                if (!world.getBlockState(floor).isSideSolidFullSquare(world, floor, net.minecraft.util.math.Direction.UP)) {
                    return reject(source, "The plots need level ground: " + floor.toShortString() + " is not solid. Stand on open, level ground.");
                }
                for (int y = 1; y <= 16; y++) {
                    var state = world.getBlockState(floor.up(y));
                    if (!state.isAir() && !state.isReplaceable()) return reject(source, "The plots need open ground: " + floor.up(y).toShortString() + " is in the way.");
                }
            }
        }
        var result = matches.proposeBuild(builders, buildTicks);
        if (!result.accepted()) return reject(source, result.reason());
        // M-06k3a: everything the battle will change, noted before anything is: the plots to build height, the arena and
        // the podium's places. Put back once the podium has been shown, at a stop, or at the next start after a crash.
        var arenaBox = arenaBox(plots, dev.kindred.core.match.BuildArena.around(plots));
        var before = ArenaSnapshots.capture(world, arenaBox);
        // The plots, marked out: white concrete, a grey edge, plants cleared off them.
        for (var plot : plots) {
            var o = plot.origin();
            for (int x = 0; x < dev.kindred.core.match.BuildBattle.PLOT; x++) for (int z = 0; z < dev.kindred.core.match.BuildBattle.PLOT; z++) {
                boolean edge = x == 0 || z == 0 || x == dev.kindred.core.match.BuildBattle.PLOT - 1 || z == dev.kindred.core.match.BuildBattle.PLOT - 1;
                BlockPos floor = new BlockPos(o.x() + x, o.y(), o.z() + z);
                world.setBlockState(floor, (edge ? Blocks.LIGHT_GRAY_CONCRETE : Blocks.WHITE_CONCRETE).getDefaultState());
                for (int y = 1; y <= 16; y++) if (!world.getBlockState(floor.up(y)).isAir()) world.setBlockState(floor.up(y), Blocks.AIR.getDefaultState());
            }
        }
        // The arena round them (M-04): a lobby pad, a raised walkway in front of the plots with a marked spot before each
        // for the vote, and room for the podium. Builder only, where blocks are free.
        var arena = dev.kindred.core.match.BuildArena.around(plots);
        for (var block : arena.blocks().entrySet()) {
            var at = new BlockPos(block.getKey().x(), block.getKey().y(), block.getKey().z());
            world.setBlockState(at, Registries.BLOCK.get(net.minecraft.util.Identifier.of(block.getValue())).getDefaultState());
        }
        var match = enter(result.match().orElseThrow());
        arenas.put(match.id(), arena);
        arenaWorlds.put(match.id(), world.getRegistryKey());
        arenaSnapshot.put(match.id(), before);
        ArenaSnapshots.close(match.id(), world.getRegistryKey(), arenaBox);
        UUID snapshotOf = match.id();
        arenaSnapshots.write(snapshotOf, before).whenComplete((done, failure) -> {
            if (failure != null) KindredMod.LOGGER.error("Build battle {}: the arena's snapshot could not be written; a crash before its restore leaves it standing",
                    dev.kindred.core.match.MatchRegistry.shortId(snapshotOf), failure);
        });
        var round = new dev.kindred.core.match.BuildBattle(theme != null ? theme : dev.kindred.core.match.BuildBattle.pick(new java.util.Random()), plots);
        battles.put(match.id(), round);
        // Reference designs for the theme: schematics the operator put in the library whose names name it and that fit a
        // plot, each kept with its credit (D8). Read off the game thread; an AI builder uses one if it is ready by the start.
        UUID roundId = match.id();
        schematics.names().thenCompose(names -> {
            var reads = names.stream().map(name -> schematics.load(name).thenApply(loaded ->
                    dev.kindred.core.match.BuildBattle.fitsTheme(name, loaded.blueprint(), round.theme()) ? loaded.blueprint() : null)
                    .exceptionally(failure -> null)).toList();
            return CompletableFuture.allOf(reads.toArray(CompletableFuture[]::new))
                    .thenApply(done -> reads.stream().map(CompletableFuture::join).filter(java.util.Objects::nonNull).toList());
        }).whenComplete((designs, failure) -> handBack(() -> {
            if (failure == null && designs != null && !designs.isEmpty() && battles.containsKey(roundId)) libraryDesigns.put(roundId, designs);
        }));
        var pad = arena.lobby();
        for (UUID builder : match.invited()) {
            var player = server.getPlayerManager().getPlayer(builder);
            if (player != null && entryForPlayer(builder) == null) {
                player.sendMessage(Text.literal("The arena's lobby is at " + pad.x() + " " + pad.y() + " " + pad.z()
                        + "; onlookers watch from the walkway in front of the plots."), false);
            }
        }
        feedback(source, "Build battle " + dev.kindred.core.match.MatchRegistry.shortId(match.id()) + " proposed: " + who(match) + ", "
                + buildTicks / 20 + " seconds to build; " + match.joined().size() + " of " + match.invited().size() + " joined.");
        return 1;
    }

    /**
     * The build begins: the theme announced, every builder in creative on its plot, and each AI builder at work on its
     * design for the theme, stocked with what the design takes (creative's free blocks, in this mode only).
     */
    private void startBuilding(dev.kindred.core.match.MatchRegistry.Match match) {
        var battle = battles.get(match.id());
        if (battle == null) return;
        for (UUID builder : match.joined()) {
            var player = server.getPlayerManager().getPlayer(builder);
            if (player == null) continue;
            // M-06k3: its own things and game mode set aside on disk before anything of theirs is touched; a builder in
            // twice keeps its first hold. Creative and the stock only once the hold is written.
            if (builderHold.containsKey(builder)) { beginBuilding(match, builder); continue; }
            var hold = BuilderHolds.capture(player);
            builderHold.put(builder, hold);
            builderHolds.write(builder, hold).whenComplete((wrote, failure) -> handBack(() -> {
                if (!running) return;
                if (failure != null) {
                    builderHold.remove(builder);
                    KindredMod.LOGGER.error("Build battle {}: {}'s things could not be set aside; it does not build", dev.kindred.core.match.MatchRegistry.shortId(match.id()),
                            playerName(builder), failure);
                    return;
                }
                var now = matches.list().stream().filter(m -> m.id().equals(match.id())).findFirst().orElse(null);
                if (now == null || now.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING || !now.playing(builder)) return;
                beginBuilding(now, builder);
            }));
        }
    }

    /** One builder into its battle, its own things already set aside: cleared, creative, an AI builder stocked. */
    private void beginBuilding(dev.kindred.core.match.MatchRegistry.Match match, UUID builder) {
        var battle = battles.get(match.id());
        var player = server.getPlayerManager().getPlayer(builder);
        if (battle == null || player == null) return;
        int seconds = matches.limit(match.id()) / 20;
        modeBefore.putIfAbsent(builder, player.interactionManager.getGameMode());
        player.getInventory().clear();
        player.getEnderChestInventory().clear();
        Entry builderEntry = entryForPlayer(builder);
        if (builderEntry != null && builderEntry.nativeBody != null) builderEntry.nativeBody.allowCreative(true);
        player.changeGameMode(net.minecraft.world.GameMode.CREATIVE);
        ArenaSnapshots.building(builder, true);
        presenter.show(builder, new dev.kindred.core.match.MatchPresentation.Title(battle.theme().title(), "Build it on your plot in "
                + seconds / 60 + ":" + String.format(java.util.Locale.ROOT, "%02d", seconds % 60), dev.kindred.core.match.MatchPresentation.Cue.START));
        Entry entry = entryForPlayer(builder);
        var plot = battle.plot(builder).orElse(null);
        if (entry == null || plot == null) return;
        var random = new java.util.Random(match.id().getLeastSignificantBits() ^ builder.getMostSignificantBits());
        // A reference design from the library for the theme where there is one (M-05), credited; else its own design.
        var library = libraryDesigns.getOrDefault(match.id(), List.of());
        var design = library.isEmpty() ? dev.kindred.core.match.BuildBattle.design(battle.theme(), random) : library.get(random.nextInt(library.size()));
        if (!library.isEmpty()) {
            String credit = "Build battle " + dev.kindred.core.match.MatchRegistry.shortId(match.id()) + ": " + playerName(builder) + " builds '"
                    + design.name() + "' from the schematic library, " + SchematicLibrary.credit(design);
            KindredMod.LOGGER.info(credit);
            for (UUID invited : match.invited()) {
                var other = server.getPlayerManager().getPlayer(invited);
                if (other != null && entryForPlayer(invited) == null) other.sendMessage(Text.literal(credit), false);
            }
        }
        var site = plot.site(design);
        stockFor(player, design);
        startBuild(server.getCommandSource(), entry.data.id(), design, new BlockPos(site.x(), site.y(), site.z()), 0);
        KindredMod.LOGGER.info("Build battle {}: {} builds {} at {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()), playerName(builder),
                design.name(), site);
    }

    /**
     * A builder out of its battle given back exactly its own things and game mode (M-06k3): everything creative made or
     * the match gave cleared, the hold put back, the player saved, then the hold forgotten. Online players only; one away
     * gets it back when it next joins.
     */
    private void restoreBuilder(ServerPlayerEntity player, net.minecraft.nbt.NbtCompound hold, boolean waitForDelete) {
        UUID id = player.getUuid();
        ArenaSnapshots.building(id, false);
        Entry entry = entryForPlayer(id);
        if (entry != null && entry.build != null) startBuild(server.getCommandSource(), entry.data.id(), null, null, 0);
        var mode = BuilderHolds.restore(player, hold);
        if (entry != null && entry.nativeBody != null) {
            entry.nativeBody.allowCreative(false);
            entry.nativeBody.allowAdventure(false);
        }
        player.changeGameMode(mode);
        if (entry != null && entry.nativeBody != null) persistNativeSaveReceipt(entry);
        else ((dev.kindred.fabric.mixin.PlayerManagerSaveInvoker) server.getPlayerManager()).kindred$saveNativePlayer(player);
        if (waitForDelete) builderHolds.deleteNow(id);
        else builderHolds.delete(id).whenComplete((done, failure) -> {
            if (failure != null) KindredMod.LOGGER.error("A builder's hold could not be deleted; it is restored again at the next login", failure);
        });
        KindredMod.LOGGER.info("Build battle: {} given back its own things and {} mode", player.getName().getString(), mode.asString());
    }

    /**
     * A battle over (M-06k3): every container on its plots and in its arena emptied and every item lying there discarded,
     * so nothing creative made leaves Builder. The builds themselves stand for the podium.
     */
    private void reclaimArena(dev.kindred.core.match.MatchRegistry.Match match) {
        var battle = battles.get(match.id());
        var key = arenaWorlds.remove(match.id());
        var world = key == null ? null : server.getWorld(key);
        if (battle == null || world == null) return;
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;
        var corners = new ArrayList<dev.kindred.core.construction.Pos>();
        for (var plot : battle.plots()) {
            var o = plot.origin();
            corners.add(o);
            corners.add(new dev.kindred.core.construction.Pos(o.x() + dev.kindred.core.match.BuildBattle.PLOT - 1, o.y() + 24, o.z() + dev.kindred.core.match.BuildBattle.PLOT - 1));
        }
        var arena = arenas.get(match.id());
        if (arena != null) corners.addAll(arena.blocks().keySet());
        for (var c : corners) {
            minX = Math.min(minX, c.x()); minY = Math.min(minY, c.y()); minZ = Math.min(minZ, c.z());
            maxX = Math.max(maxX, c.x()); maxY = Math.max(maxY, c.y() + 8); maxZ = Math.max(maxZ, c.z());
        }
        if (corners.isEmpty()) return;
        int emptied = 0, discarded = 0;
        for (int cx = minX >> 4; cx <= maxX >> 4; cx++) for (int cz = minZ >> 4; cz <= maxZ >> 4; cz++) {
            if (!world.isChunkLoaded(cx, cz)) continue;
            for (var blockEntity : new ArrayList<>(world.getChunk(cx, cz).getBlockEntities().values())) {
                var at = blockEntity.getPos();
                if (at.getX() < minX || at.getX() > maxX || at.getY() < minY || at.getY() > maxY || at.getZ() < minZ || at.getZ() > maxZ) continue;
                if (blockEntity instanceof net.minecraft.inventory.Inventory inventory && !inventory.isEmpty()) {
                    inventory.clear();
                    blockEntity.markDirty();
                    emptied++;
                }
            }
        }
        var box = new net.minecraft.util.math.Box(minX, minY, minZ, maxX + 1, maxY + 1, maxZ + 1);
        for (var item : world.getEntitiesByClass(net.minecraft.entity.ItemEntity.class, box, e -> true)) {
            item.discard();
            discarded++;
        }
        if (emptied > 0 || discarded > 0) {
            KindredMod.LOGGER.info("Build battle {}: {} containers emptied and {} items lying about cleared from the arena", dev.kindred.core.match.MatchRegistry.shortId(match.id()),
                    emptied, discarded);
        }
    }

    /** The box a battle changes: its plots to 32 over their floors, the arena, and the podium's places and signs. */
    private static net.minecraft.util.math.BlockBox arenaBox(List<dev.kindred.core.match.BuildBattle.Plot> plots, dev.kindred.core.match.BuildArena arena) {
        var points = new ArrayList<dev.kindred.core.construction.Pos>();
        for (var plot : plots) {
            var o = plot.origin();
            points.add(o);
            points.add(new dev.kindred.core.construction.Pos(o.x() + dev.kindred.core.match.BuildBattle.PLOT - 1, o.y() + 32, o.z() + dev.kindred.core.match.BuildBattle.PLOT - 1));
        }
        points.addAll(arena.blocks().keySet());
        points.addAll(arena.podiumBlocks(3).keySet());
        points.addAll(arena.podium());
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;
        for (var p : points) {
            minX = Math.min(minX, p.x()); minY = Math.min(minY, p.y()); minZ = Math.min(minZ, p.z());
            maxX = Math.max(maxX, p.x()); maxY = Math.max(maxY, p.y() + 2); maxZ = Math.max(maxZ, p.z());
        }
        return new net.minecraft.util.math.BlockBox(minX, minY, minZ, maxX, maxY, maxZ);
    }

    /** Each finished battle whose podium has been shown long enough: its arena put back (M-06k3a). */
    private void restoreArenasDue() {
        long now = server.getTicks();
        for (var due : new ArrayList<>(arenaRestoreAt.entrySet())) {
            if (due.getValue() > now) continue;
            if (restoreArena(due.getKey(), false)) arenaRestoreAt.remove(due.getKey());
        }
    }

    /**
     * A battle's arena put back as it was, dropping nothing, its containers emptied and items cleared first (M-06k3a).
     * False when its chunks are not all loaded yet: they are asked for, and it is tried again next time.
     */
    private boolean restoreArena(UUID match, boolean atStop) {
        var snapshot = arenaSnapshot.get(match);
        if (snapshot == null) { ArenaSnapshots.open(match); return true; }
        var world = server.getWorld(ArenaSnapshots.world(snapshot));
        if (world == null) return true;
        if (!ArenaSnapshots.loaded(world, snapshot)) {
            if (atStop) return false;
            var box = ArenaSnapshots.box(snapshot);
            for (int cx = box.getMinX() >> 4; cx <= box.getMaxX() >> 4; cx++) for (int cz = box.getMinZ() >> 4; cz <= box.getMaxZ() >> 4; cz++) {
                var chunk = new net.minecraft.util.math.ChunkPos(cx, cz);
                world.getChunkManager().addTicket(NATIVE_CONNECT, chunk, 1, chunk);
            }
            return false;
        }
        int changed = ArenaSnapshots.restore(world, snapshot);
        arenaSnapshot.remove(match);
        ArenaSnapshots.open(match);
        arenaSnapshots.markRestored(match);
        KindredMod.LOGGER.info("Build battle {}: the arena put back as it was ({} blocks)", dev.kindred.core.match.MatchRegistry.shortId(match), changed);
        for (var player : world.getPlayers()) {
            if (ArenaSnapshots.box(snapshot).contains(player.getBlockPos())) player.sendMessage(Text.literal("The arena is cleared.").formatted(net.minecraft.util.Formatting.GOLD), false);
        }
        return true;
    }

    /** At the start: an arena a crash left standing, put back as soon as its ground is loaded (M-06k3a). */
    private void restoreLeftoverArenas() {
        arenaSnapshots.readAll().whenComplete((left, failure) -> handBack(() -> {
            if (!running || failure != null || left == null) {
                if (failure != null) KindredMod.LOGGER.error("Arena snapshots could not be read at the start", failure);
                return;
            }
            for (var each : left.entrySet()) {
                if (arenaSnapshot.containsKey(each.getKey())) continue;
                arenaSnapshot.put(each.getKey(), each.getValue());
                ArenaSnapshots.close(each.getKey(), ArenaSnapshots.world(each.getValue()), ArenaSnapshots.box(each.getValue()));
                arenaRestoreAt.put(each.getKey(), (long) server.getTicks());
                KindredMod.LOGGER.info("Build battle {}: a crash left its arena standing; it is put back now", dev.kindred.core.match.MatchRegistry.shortId(each.getKey()));
            }
        }));
    }

    /** For fixtures: the podium's time before the arena is put back, in ticks. */
    void arenaShownTicksForTest(int ticks) { requireThread(); arenaShownTicks = ticks; }

    /** For fixtures: whether a battle's arena is still waiting to be put back. */
    boolean arenaPendingForTest(UUID match) { requireThread(); return arenaSnapshot.containsKey(match); }

    /** For fixtures: whether a battle's restored arena's snapshot still waits for a whole save. */
    boolean arenaAwaitingSaveForTest(UUID match) { requireThread(); return arenaSnapshots.awaitingSave(match); }

    /** A player joining with a hold left from a battle it was away for at the end, or one a crash cut short (M-06k3). */
    private void restoreHoldOnJoin(ServerPlayerEntity player) {
        UUID id = player.getUuid();
        if (builderHold.containsKey(id) || !holdsRestoring.add(id)) return;
        builderHolds.read(id).whenComplete((hold, failure) -> handBack(() -> {
            holdsRestoring.remove(id);
            if (!running || failure != null || hold == null || hold.isEmpty() || builderHold.containsKey(id)) {
                if (failure != null) KindredMod.LOGGER.error("{}'s builder hold could not be read; it stays for an operator", player.getName().getString(), failure);
                return;
            }
            var now = server.getPlayerManager().getPlayer(id);
            if (now == null || now.isDisconnected()) return;
            restoreBuilder(now, hold.get(), false);
        }));
    }

    /** An AI builder's inventory filled with what its design takes, and scaffolding: free in creative, in Builder only. */
    private static void stockFor(ServerPlayerEntity player, dev.kindred.core.construction.Blueprint design) {
        var counts = new java.util.LinkedHashMap<String, Integer>();
        for (var b : design.blocks()) counts.merge(dev.kindred.core.construction.Placement.item(b.spec()), 1, Integer::sum);
        counts.merge("minecraft:dirt", 64, Integer::sum);
        var inventory = player.getInventory();
        int slot = 0;
        EvalItemSources.enter(player);
        for (var e : counts.entrySet()) {
            var item = net.minecraft.registry.Registries.ITEM.get(net.minecraft.util.Identifier.of(e.getKey()));
            for (int left = e.getValue(); left > 0 && slot < 36; left -= 64) inventory.setStack(slot++, new ItemStack(item, Math.min(64, left)));
        }
        EvalItemSources.exit(player, "rule:builder-stock");
    }

    /** The blocks standing on a plot, over its floor, by kind: what a voter sees of a build. */
    private Map<dev.kindred.core.construction.Pos, String> plotBlocks(net.minecraft.server.world.ServerWorld world, dev.kindred.core.match.BuildBattle.Plot plot) {
        var out = new HashMap<dev.kindred.core.construction.Pos, String>();
        var o = plot.origin();
        for (int x = 0; x < dev.kindred.core.match.BuildBattle.PLOT; x++) for (int z = 0; z < dev.kindred.core.match.BuildBattle.PLOT; z++) for (int y = 1; y <= 24; y++) {
            var state = world.getBlockState(new BlockPos(o.x() + x, o.y() + y, o.z() + z));
            if (!state.isAir()) out.put(new dev.kindred.core.construction.Pos(x, y, z), net.minecraft.registry.Registries.BLOCK.getId(state.getBlock()).toString());
        }
        return out;
    }

    /**
     * The build's time is up: building stops, every builder's creative blocks are cleared and it looks on in adventure
     * mode while each votes. An AI builder votes at once, as the judge scores what stands on each other plot; a human is
     * offered the votes to click.
     */
    private void startVoting(dev.kindred.core.match.MatchRegistry.Match match) {
        var battle = battles.get(match.id());
        if (battle == null) return;
        for (UUID builder : match.joined()) {
            var player = server.getPlayerManager().getPlayer(builder);
            if (player == null) continue;
            Entry entry = entryForPlayer(builder);
            if (entry != null && entry.build != null) startBuild(server.getCommandSource(), entry.data.id(), null, null, 0);
            if (entry != null && entry.nativeBody != null) {
                // Its hands are emptied and its game mode changed only once what it was doing has settled: an action
                // caught half done by the change, cut short to make way for it, or with its block taken from its hand,
                // leaves an outcome only reconciliation can settle, and the body is taken out (found live, three times).
                // With its build stopped, nothing new begins meanwhile.
                toAdventure.add(entry.data.id());
                continue;
            }
            player.getInventory().clear();
            player.changeGameMode(net.minecraft.world.GameMode.ADVENTURE);
        }
        // The builds are then shown one at a time, each for its share of the vote (pollBuildBattles): every voter walks
        // to the marked spot in front of it and votes on what it sees from there.
        showingNow.remove(match.id());
    }

    /** A builder's vote on another's build, one to five, while the round is voted on. */
    int voteBuild(ServerCommandSource source, UUID builder, int score) {
        requireThread();
        if (!(source.getEntity() instanceof ServerPlayerEntity voter)) return reject(source, "Only a builder votes, for itself.");
        var match = matches.active(voter.getUuid()).filter(m -> m.mode() == dev.kindred.core.match.MatchRegistry.Mode.BUILDER).orElse(null);
        if (match == null || match.state() != dev.kindred.core.match.MatchRegistry.State.VOTING) return reject(source, "No build battle of yours is being voted on.");
        // One build at a time, the same for everyone: the one being shown.
        if (!builder.equals(dev.kindred.core.match.MatchRegistry.showing(match, server.getTicks()).orElse(null))) {
            return reject(source, "That build is not the one being voted on now.");
        }
        var battle = battles.get(match.id());
        var refused = battle == null ? java.util.Optional.of("No such round") : battle.vote(voter.getUuid(), builder, score);
        if (refused.isPresent()) return reject(source, refused.get() + ".");
        feedback(source, "Voted " + score + " for " + playerName(builder) + "'s build.");
        return 1;
    }

    /** Once a second: a vote everyone has finished, or whose time is up, decided. */
    private void pollBuildBattles() {
        for (var match : matches.list()) {
            if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.BUILDER || match.state() != dev.kindred.core.match.MatchRegistry.State.VOTING) continue;
            var battle = battles.get(match.id());
            if (battle == null) continue;
            showBuild(match, battle);
            boolean all = match.joined().stream().filter(match::playing).allMatch(battle::votedAll);
            if (!all && server.getTicks() < match.endsAt()) continue;
            var winners = battle.winners();
            matches.decide(match.id(), winners, winners.isEmpty() ? "Nobody voted" : "the best mean vote").match().ifPresent(this::announce);
        }
    }

    /**
     * Builders out of their build battle (it ended, or they left it): creative's blocks cleared and their own game mode
     * back, and each AI builder's build stopped. At the end, fireworks over the winners' plots.
     */
    private void leaveBuilding(dev.kindred.core.match.MatchRegistry.Match match) {
        boolean over = match.state() == dev.kindred.core.match.MatchRegistry.State.ENDED;
        for (UUID builder : match.invited()) {
            if (!over && match.playing(builder)) continue;
            modeBefore.remove(builder);
            ArenaSnapshots.building(builder, false);
            var hold = builderHold.remove(builder);
            if (hold == null) continue;
            // Away at the end: its hold stays on disk, and it gets its own things back when it next joins (M-06k3).
            var player = server.getPlayerManager().getPlayer(builder);
            if (player == null) continue;
            restoreBuilder(player, hold, false);
        }
        if (over) reclaimArena(match);
        var battle = battles.get(match.id());
        if (!over || battle == null) return;
        var world = server.getOverworld();
        for (UUID winner : match.winners()) {
            battle.plot(winner).ifPresent(plot -> {
                var rocket = new ItemStack(Items.FIREWORK_ROCKET);
                rocket.set(net.minecraft.component.DataComponentTypes.FIREWORKS, new net.minecraft.component.type.FireworksComponent(1, List.of(
                        new net.minecraft.component.type.FireworkExplosionComponent(net.minecraft.component.type.FireworkExplosionComponent.Type.LARGE_BALL,
                                it.unimi.dsi.fastutil.ints.IntList.of(0xFFD700, 0xFFFFFF), it.unimi.dsi.fastutil.ints.IntList.of(), true, true))));
                var o = plot.origin();
                for (int i = 0; i < 3; i++) {
                    world.spawnEntity(new net.minecraft.entity.projectile.FireworkRocketEntity(world, o.x() + 3.5 + i * 4, o.y() + 1.5, o.z() + 7.5, rocket.copy()));
                }
            });
        }
        // The podium (M-04): the best three by their mean vote, first in the middle, each named on a sign atop its step.
        var arena = arenas.remove(match.id());
        showingNow.remove(match.id());
        if (arena != null && !battle.scores().isEmpty()) {
            var ranked = battle.scores().entrySet().stream().sorted(Map.Entry.<UUID, Double>comparingByValue().reversed()).limit(3).toList();
            for (var block : arena.podiumBlocks(ranked.size()).entrySet()) {
                var at = new BlockPos(block.getKey().x(), block.getKey().y(), block.getKey().z());
                world.setBlockState(at, Registries.BLOCK.get(net.minecraft.util.Identifier.of(block.getValue())).getDefaultState());
            }
            var names = new ArrayList<String>();
            String[] places = {"1st", "2nd", "3rd"};
            for (int i = 0; i < ranked.size(); i++) {
                var top = arena.podium().get(i);
                var at = new BlockPos(top.x(), top.y(), top.z());
                // Facing west, back along the walkway, to whoever comes along it.
                world.setBlockState(at, Blocks.OAK_SIGN.getDefaultState().with(net.minecraft.block.SignBlock.ROTATION, 4));
                String name = playerName(ranked.get(i).getKey());
                names.add(name);
                if (world.getBlockEntity(at) instanceof net.minecraft.block.entity.SignBlockEntity sign) {
                    sign.setText(new net.minecraft.block.entity.SignText()
                            .withMessage(0, Text.literal(places[i]))
                            .withMessage(1, Text.literal(name))
                            .withMessage(2, Text.literal(String.format(java.util.Locale.ROOT, "%.1f of 5", ranked.get(i).getValue()))), true);
                }
            }
            podiums.put(match.id(), List.copyOf(names));
            KindredMod.LOGGER.info("Build battle {}: the podium {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()), names);
        }
        // The podium shown, then the arena put back at an announced moment (M-06k3a); closed to breaking till then.
        if (arenaSnapshot.containsKey(match.id())) {
            arenaRestoreAt.put(match.id(), (long) server.getTicks() + arenaShownTicks);
            String when = "The arena is cleared after the podium, in " + Math.max(1, arenaShownTicks / 20) + " seconds.";
            for (UUID invited : match.invited()) {
                var other = server.getPlayerManager().getPlayer(invited);
                if (other != null) other.sendMessage(Text.literal(when).formatted(net.minecraft.util.Formatting.GOLD), false);
            }
            KindredMod.LOGGER.info("Build battle {}: {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()), when);
        }
        battles.remove(match.id());
        libraryDesigns.remove(match.id());
        buildsBegun.remove(match.id());
    }

    /** The names on each finished round's podium, first first, for a fixture. */
    private final Map<UUID, List<String>> podiums = new HashMap<>();

    List<String> podiumForTest(UUID matchId) {
        requireThread();
        return podiums.getOrDefault(matchId, List.of());
    }

    /** A round's arena, for a fixture. */
    dev.kindred.core.match.BuildArena arenaForTest(UUID matchId) {
        requireThread();
        return arenas.get(matchId);
    }

    /**
     * Whether {@code player} may break or place at {@code pos} with a build battle on (M-04a): while it builds, a builder
     * only on its own plot; nobody on another's plot, in the battle or not. Anywhere else, as ever.
     */
    /**
     * Whether {@code player} may place a block at {@code target} against {@code clicked} (M-04): the target must be its to
     * edit, and so must the block clicked, unless that is the floor of its own plot in a running build battle, which a
     * builder builds on but does not change.
     */
    boolean mayPlace(ServerPlayerEntity player, BlockPos clicked, BlockPos target) {
        if (!mayEditAt(player, target)) return false;
        if (mayEditAt(player, clicked)) return true;
        for (var match : matches.list()) {
            if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.BUILDER || match.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING
                    || !match.playing(player.getUuid())) continue;
            var plot = battles.containsKey(match.id()) ? battles.get(match.id()).plot(player.getUuid()).orElse(null) : null;
            if (plot == null) continue;
            var o = plot.origin();
            if (clicked.getY() == o.y() && clicked.getX() >= o.x() && clicked.getX() < o.x() + dev.kindred.core.match.BuildBattle.PLOT
                    && clicked.getZ() >= o.z() && clicked.getZ() < o.z() + dev.kindred.core.match.BuildBattle.PLOT) return true;
        }
        return false;
    }

    boolean mayEditAt(ServerPlayerEntity player, BlockPos pos) {
        if (!running) return true;
        var at = new dev.kindred.core.construction.Pos(pos.getX(), pos.getY(), pos.getZ());
        for (var match : matches.list()) {
            if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.BUILDER || match.state() == dev.kindred.core.match.MatchRegistry.State.ENDED) continue;
            var battle = battles.get(match.id());
            if (battle == null) continue;
            var own = battle.plot(player.getUuid()).filter(p -> match.playing(player.getUuid()));
            boolean onAPlot = battle.plots().stream().anyMatch(p -> p.contains(at));
            if (onAPlot && (own.isEmpty() || !own.get().contains(at) || match.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING)) return false;
            // A human builder keeps to its plot while it builds; an AI builder's scaffold may stand in the gap beside it.
            if (own.isPresent() && match.state() == dev.kindred.core.match.MatchRegistry.State.RUNNING && !onAPlot && entryForPlayer(player.getUuid()) == null) return false;
        }
        return true;
    }

    /** Whether vanilla has given {@code player} the split's advancement. */
    private boolean reached(ServerPlayerEntity player, dev.kindred.core.match.SpeedrunSplits.Split split) {
        var advancement = server.getAdvancementLoader().get(net.minecraft.util.Identifier.of(split.advancement()));
        return advancement != null && player.getAdvancementTracker().getProgress(advancement).isDone();
    }

    /**
     * A race or a hunt begins: each AI runner set to the dragon goal, at speedrun pace in a race and at a reliable pace in
     * a hunt; each AI hunter to the run's own route, which earns its tools and the iron for its kit (M-02a, M-02b). Their
     * own pace is kept to give back.
     */
    private void startRace(dev.kindred.core.match.MatchRegistry.Match match) {
        boolean hunt = match.mode() == dev.kindred.core.match.MatchRegistry.Mode.MANHUNT;
        if (hunt) hunts.add(match.id());
        else races.put(match.id(), new dev.kindred.core.match.SpeedrunSplits(server.getTicks()));
        for (UUID player : match.joined()) {
            Entry entry = entryForPlayer(player);
            if (entry == null) continue;
            racePace.put(entry.data.id(), entry.runtimeSettings.playstyleProfile());
            var goal = match.runners().contains(player) ? dev.kindred.core.survival.SurvivalGoal.DRAGON : dev.kindred.core.survival.SurvivalGoal.NETHER_PORTAL;
            // A race's runner goes at speedrun pace; a manhunt's beats the game quickly but reliably, at its own pace (M-02b).
            if (match.runners().contains(player)) {
                entry.runtimeSettings = entry.runtimeSettings.withPlaystyle(hunt ? PlaystyleProfile.OPTIMAL_SURVIVAL : PlaystyleProfile.SPEEDRUN_ANY_PERCENT);
            }
            raceGoal.put(entry.data.id(), goal);
            beginGoal(entry, goal);
            if (entry.snapshot().stopLatched()) nativeLifecycle(server.getCommandSource(), "resume", entry.data.id());
        }
        if (hunt) {
            // The one item the hunt hands out, announced before it is, the same for every hunter (D6).
            String rule = "Rule: every hunter holds a tracking compass. It points at the nearest runner in the hunter's world, or where a "
                    + "runner last left it; it vanishes when its hunter dies and is given again, and every one is taken back when the hunt ends.";
            int head = matches.headStart(match.id());
            if (head > 0) {
                // The runners' head start (M-02b): every hunter held where it stands, human or AI alike, and nobody strikes.
                rule += " The runners have a head start of " + head / 20 + " seconds: until it is over, every hunter is held where it stands and nobody may strike.";
                heldHunts.put(match.id(), match.countdownEnds() + head);
                for (UUID hunter : match.joined()) if (match.hunter(hunter)) hold(server.getPlayerManager().getPlayer(hunter), true);
            }
            for (UUID invited : match.invited()) {
                var player = server.getPlayerManager().getPlayer(invited);
                if (player != null) player.sendMessage(Text.literal(rule).formatted(net.minecraft.util.Formatting.GOLD), false);
            }
            pollHunts();
        }
    }

    /** Manhunts in their runners' head start: when each ends, by tick. */
    private final Map<UUID, Long> heldHunts = new HashMap<>();
    private static final net.minecraft.util.Identifier HELD = net.minecraft.util.Identifier.of("kindred", "head_start");

    /** A hunter held where it stands for the head start, or let go: no walking, no jumping (M-02b). Not saved. */
    private static void hold(ServerPlayerEntity player, boolean held) {
        if (player == null) return;
        for (var attribute : List.of(net.minecraft.entity.attribute.EntityAttributes.GENERIC_MOVEMENT_SPEED,
                net.minecraft.entity.attribute.EntityAttributes.GENERIC_JUMP_STRENGTH)) {
            var instance = player.getAttributeInstance(attribute);
            if (instance == null) continue;
            instance.removeModifier(HELD);
            if (held) instance.addTemporaryModifier(new net.minecraft.entity.attribute.EntityAttributeModifier(HELD, -1.0,
                    net.minecraft.entity.attribute.EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        }
    }

    /** Each tick: a head start that is over lets its hunters go, and says so; an ended hunt's hunters let go at once. */
    private void releaseHunts(long tick) {
        for (var it = heldHunts.entrySet().iterator(); it.hasNext(); ) {
            var held = it.next();
            var match = matches.get(held.getKey()).orElse(null);
            boolean over = match == null || match.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING;
            if (!over && tick < held.getValue()) continue;
            it.remove();
            if (match == null) continue;
            for (UUID hunter : match.invited()) if (match.hunter(hunter)) hold(server.getPlayerManager().getPlayer(hunter), false);
            if (over) continue;
            KindredMod.LOGGER.info("Manhunt {}: the head start is over", dev.kindred.core.match.MatchRegistry.shortId(match.id()));
            for (UUID invited : match.invited()) {
                var player = server.getPlayerManager().getPlayer(invited);
                if (player != null) player.sendMessage(Text.literal("The head start is over: the hunters are free.").formatted(net.minecraft.util.Formatting.GOLD), false);
                Entry entry = entryForPlayer(invited);
                if (entry != null) {
                    entry.cachedRoutineCandidates = List.of();
                    entry.routineRefreshPending = true;
                }
            }
        }
    }

    /** Whether a hunter is held by its manhunt's head start now, for a fixture. */
    boolean heldForTest(UUID player) {
        requireThread();
        return matches.running(player).filter(m -> m.hunter(player) && matches.heldBack(m, server.getTicks())).isPresent();
    }

    /**
     * Whether a strike by {@code attacker} at {@code target}, both players, is refused by their match's rules: both in the
     * same match that has not ended, and the match does not let them strike one another now (its lobby, countdown or
     * head start, the same side, or a mode with no striking). The same for humans and AI players. Outside matches the
     * server's own rules stand.
     */
    boolean matchForbidsStrike(UUID attacker, UUID target) {
        requireThread();
        // A faction world is a match every faction member joined (M-06c, D7): a strike between players stands only where
        // a match or the faction rules allow it, for people and AI players alike.
        if (factionsWorld()) return !matches.mayAttack(attacker, target) && !factions.mayAttack(attacker, target);
        var match = matches.active(attacker).orElse(null);
        if (match == null || !match.invited().contains(target) || match.out().contains(target)) return false;
        return !matches.mayAttack(attacker, target);
    }

    /** An AI runner out of its race (it ended, or the runner dropped out): the race's goal ends and its own pace is back. */
    private void leaveRace(dev.kindred.core.match.MatchRegistry.Match match) {
        for (UUID runner : match.joined()) {
            if (match.state() != dev.kindred.core.match.MatchRegistry.State.ENDED && match.playing(runner)) continue;
            Entry entry = entryForPlayer(runner);
            if (entry == null) continue;
            var pace = racePace.remove(entry.data.id());
            if (pace == null) continue;
            if (entry.goal == raceGoal.remove(entry.data.id())) {
                entry.goal = dev.kindred.core.survival.SurvivalGoal.NONE;
                entry.goalProgress = "";
                if (entry.nativeBody != null) entry.nativeBody.setPortalTravelAuthorized(false);
                entry.cachedRoutineCandidates = List.of();
                entry.routineRefreshPending = true;
            }
            entry.runtimeSettings = entry.runtimeSettings.withPlaystyle(pace);
        }
    }

    /** The compasses a hunt handed out, taken back from each player out of it, all of them once it is over (D6). */
    private void takeBackCompasses(dev.kindred.core.match.MatchRegistry.Match match) {
        if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.MANHUNT) return;
        boolean over = match.state() == dev.kindred.core.match.MatchRegistry.State.ENDED;
        for (UUID invited : match.invited()) {
            if (!over && match.playing(invited)) continue;
            var player = server.getPlayerManager().getPlayer(invited);
            if (player != null && HuntCompass.takeBack(player, match.id()) > 0) {
                KindredMod.LOGGER.info("Manhunt {}: the tracking compass taken back from {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()), playerName(invited));
            }
        }
        if (over) {
            huntsOver.add(match.id());
            var issued = huntIssued.remove(match.id());
            if (issued != null) issued.values().forEach(HuntCompass::forget);
            hunts.remove(match.id());
            for (UUID runner : match.runners()) trails.remove(runner);
        }
    }

    /**
     * Once a second, each running hunt's compasses: every runner's place noted in its world, and every hunter's compass
     * set to the nearest runner in the hunter's world, or failing one, the nearest place a runner last left it. A hunter
     * with none (a new one, or one on its feet after a death took it) is handed one.
     */
    private void pollHunts() {
        // A hunt's compass outlives its hunt only where no player holds it (a chest, the ground): taken back wherever it
        // next turns up in a player's inventory, cursor or ender chest (M-06k2). Only the hunts this runtime saw end.
        if (!huntsOver.isEmpty()) {
            for (var player : server.getPlayerManager().getPlayerList()) {
                if (HuntCompass.sweep(player, huntsOver) > 0) KindredMod.LOGGER.info("Manhunt: a tracking compass of a hunt now over taken back from {}", player.getName().getString());
            }
        }
        for (var match : matches.list()) {
            if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.MANHUNT || match.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING) continue;
            var runners = new ArrayList<ServerPlayerEntity>();
            for (UUID runner : match.runners()) {
                var player = match.playing(runner) ? server.getPlayerManager().getPlayer(runner) : null;
                if (player == null || !player.isAlive()) continue;
                runners.add(player);
                trails.computeIfAbsent(runner, id -> new HashMap<>()).put(player.getWorld().getRegistryKey(), player.getBlockPos());
            }
            for (UUID hunterId : match.joined()) {
                if (match.runners().contains(hunterId) || !match.playing(hunterId)) continue;
                var hunter = server.getPlayerManager().getPlayer(hunterId);
                if (hunter == null) continue;
                var world = hunter.getWorld().getRegistryKey();
                BlockPos at = runners.stream().filter(r -> r.getWorld().getRegistryKey() == world)
                        .min(java.util.Comparator.comparingDouble(hunter::squaredDistanceTo)).map(ServerPlayerEntity::getBlockPos)
                        .orElseGet(() -> match.runners().stream().filter(match::playing).map(trails::get).filter(java.util.Objects::nonNull)
                                .map(trail -> trail.get(world)).filter(java.util.Objects::nonNull)
                                .min(java.util.Comparator.comparingDouble(pos -> pos.getSquaredDistance(hunter.getPos()))).orElse(null));
                var target = at == null ? java.util.Optional.<net.minecraft.util.math.GlobalPos>empty() : java.util.Optional.of(net.minecraft.util.math.GlobalPos.create(world, at));
                HuntCompass.aim(hunter, match.id(), target);
                // Issued once (M-06k2): the first at the start, another only when the hunter's own is provably gone.
                var issued = huntIssued.computeIfAbsent(match.id(), id -> new HashMap<>());
                UUID own = issued.get(hunterId);
                if (own != null && (HuntCompass.holds(hunter, own) || !HuntCompass.gone(own))) continue;
                UUID next = UUID.randomUUID();
                if (HuntCompass.issue(hunter, match.id(), next, target)) {
                    if (own != null) HuntCompass.forget(own);
                    issued.put(hunterId, next);
                    KindredMod.LOGGER.info("Manhunt {}: a tracking compass {} {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()),
                            own == null ? "issued to" : "issued again, its own destroyed, to", playerName(hunterId));
                }
            }
        }
    }

    /** A hunter's kit, ready for the hunt: a sword of iron or better and a shield (M-02a). */
    static boolean huntReady(ServerPlayerEntity player) {
        var inventory = player.getInventory();
        boolean sword = false, shield = player.getOffHandStack().isOf(Items.SHIELD);
        for (int slot = 0; slot < inventory.size(); slot++) {
            var stack = inventory.getStack(slot);
            sword |= FollowUps.ironOrBetter(stack);
            shield |= stack.isOf(Items.SHIELD);
        }
        return sword && shield;
    }

    /** A manhunt's hunter still making its kit, whose follow-ups ask for the kit first. */
    private boolean gearingHunter(NativePlayerBody body) {
        var player = body.entity();
        if (player == null) return false;
        return matches.running(player.getUuid()).filter(m -> m.hunter(player.getUuid())).isPresent() && !huntReady(player);
    }

    /**
     * What a hunter in a running manhunt does (M-02a): a runner it can see within a chase's reach is fought, kit or none,
     * as the chance comes. Kitted, it follows its compass's needle, as a player does, never told where the runner is.
     * Null when the player hunts nobody, or is still making its kit with no runner in sight (its goal's own work).
     */
    private List<NativeTaskCandidate> huntCandidates(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var match = matches.running(player.getUuid()).filter(m -> m.hunter(player.getUuid())).orElse(null);
        if (match == null) return null;
        // The runners' head start: held where it stands, it does nothing, as a held human hunter can do nothing.
        if (matches.heldBack(match, server.getTicks())) return List.of();
        UUID taskId = UUID.nameUUIDFromBytes(("hunt:" + match.id() + ":" + player.getUuid()).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        ServerPlayerEntity prey = null;
        for (UUID runner : match.runners()) {
            var target = match.playing(runner) ? server.getPlayerManager().getPlayer(runner) : null;
            if (target == null || !target.isAlive() || target.getServerWorld() != player.getServerWorld() || player.squaredDistanceTo(target) > 24 * 24
                    || !player.canSee(target)) continue;
            if (prey == null || player.squaredDistanceTo(target) < player.squaredDistanceTo(prey)) prey = target;
        }
        long now = server.getTicks();
        if (prey != null) {
            entry.preySeen = prey.getBlockPos().toImmutable();
            entry.preySeenAt = now;
        }
        if (now - entry.fightStalledAt < STALLED_FIGHT && entry.preySeen != null && now - entry.preySeenAt < STALLED_FIGHT) {
            // Its last fight could not close in (a runner up a tower, across a gap): it makes a way to where it last saw
            // the runner as a player does, with its own blocks, digging and stairs, rather than start the same fight
            // again (M-02a).
            var way = wayTo(entry, body, entry.preySeen);
            if (way != null) return way;
        }
        if (prey != null) {
            var fight = new dev.kindred.core.TaskPreferences.Candidate(taskId, dev.kindred.core.TaskPreferences.Priority.URGENT, 99.0,
                    dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
            int slot = Weapons.choose(player, NativePlayerBody.believedHealth(player, prey), true).map(Weapons.Held::slot).orElse(-1);
            return List.of(new NativeTaskCandidate(fight, "native_fight", Map.of("target", prey.getUuid().toString(), "slot", String.valueOf(slot))));
        }
        // A runner's chest it saw them use, raided at the model's call or its own rule's (E-44), before it gears up.
        var raid = raidCandidates(entry, body);
        if (raid != null) return raid;
        // In a faction world, what the faction world asks of it (M-06i): survival's urgent needs still come first.
        var faction = factionCandidates(entry, body);
        if (faction != null) return faction;
        if (!huntReady(player)) return null;
        // Gearing up as the hunt goes on (M-02b): iron armour it carries put on, and the next piece made from the iron in
        // hand, before the needle is followed on.
        var wear = equipCandidate(entry, body, dev.kindred.core.TaskPreferences.Priority.PROJECT, 92.0);
        if (wear.isPresent()) return List.of(wear.get());
        var better = betterArmour(entry, body);
        if (better != null) return better;
        var gear = hunterArmour(entry, body);
        if (gear != null) return gear;
        var bearing = HuntCompass.bearing(player, match.id());
        if (bearing.isEmpty()) return null;
        BlockPos toward = HuntCompass.along(player.getBlockPos(), bearing.get(), 16);
        // A walk along the needle that has just failed: it makes a way along it instead, and with no way to make, it gets
        // on with its goal's work for now (a hunter in a cave walked at rock over nine thousand times in a live hunt).
        if (now - entry.walkFailedAt < 100) {
            var way = wayTo(entry, body, toward);
            return way;
        }
        var follow = new dev.kindred.core.TaskPreferences.Candidate(taskId, dev.kindred.core.TaskPreferences.Priority.PROJECT, 90.0,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(follow, "native_goto", Map.of("x", String.valueOf(toward.getX()), "y", String.valueOf(toward.getY()),
                "z", String.valueOf(toward.getZ()), "range", "3", "partial", "true", "sprint", "true")));
    }

    /**
     * Armour it carries that guards better than what it wears in that slot, swapped on as a player swaps it with the
     * number key over the armour slot (M-02b): readied to the hotbar first if it is further in. Null when it carries none.
     */
    private List<NativeTaskCandidate> betterArmour(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var inventory = player.getInventory();
        for (int slot = 0; slot < 36; slot++) {
            var stack = inventory.getStack(slot);
            if (!(stack.getItem() instanceof net.minecraft.item.ArmorItem piece) || stack.getCount() != 1) continue;
            var worn = player.getEquippedStack(player.getPreferredEquipmentSlot(stack));
            if (worn.isEmpty() || worn.getItem() instanceof net.minecraft.item.ArmorItem on && on.getProtection() >= piece.getProtection()) continue;
            // Gold worn in the Nether stays on: it keeps piglins neutral (E-07e).
            if (FollowUps.golden(worn) && player.getServerWorld().getRegistryKey() == net.minecraft.world.World.NETHER) continue;
            UUID id = UUID.nameUUIDFromBytes(("wear:" + entry.data.id() + ":" + slot).getBytes(StandardCharsets.UTF_8));
            var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.PROJECT, 92.0,
                    dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
            if (slot >= 9) {
                int hotbar = 8;
                for (int h = 0; h < 9; h++) if (inventory.getStack(h).isEmpty()) { hotbar = h; break; }
                return List.of(new NativeTaskCandidate(candidate, "native_swap", Map.of("source", String.valueOf(slot), "target", String.valueOf(hotbar))));
            }
            if (body.wearDestination(slot).isEmpty()) continue;
            return List.of(new NativeTaskCandidate(candidate, "native_equip", Map.of("slot", String.valueOf(slot), "swap", "true")));
        }
        return null;
    }

    /** How long after a fight that could not close in a hunter makes its own way to the runner instead. */
    private static final int STALLED_FIGHT = 20 * 30;

    /**
     * A way made to {@code at}: where it is two or more blocks up, a walk to its foot and a pillar of its own filler
     * blocks up beside it; otherwise the run's own route builder (bridges, stairs and pillars of its own blocks, digging
     * through), to within two blocks of it. Null when there is none, and the fight is tried again.
     */
    private List<NativeTaskCandidate> wayTo(Entry entry, NativePlayerBody body, BlockPos at) {
        if (!worldEditsEnabled()) return null;
        var player = body.entity();
        BlockPos feet = player.getBlockPos();
        double dx = at.getX() + 0.5 - player.getX(), dz = at.getZ() + 0.5 - player.getZ();
        int rise = at.getY() - feet.getY();
        if (rise >= 2) {
            UUID climbId = UUID.nameUUIDFromBytes(("climb:" + entry.data.id() + ":" + feet.asLong()).getBytes(StandardCharsets.UTF_8));
            var climb = new dev.kindred.core.TaskPreferences.Candidate(climbId, dev.kindred.core.TaskPreferences.Priority.URGENT, 98.0,
                    dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
            if (dx * dx + dz * dz > 2.5 * 2.5) {
                // To the foot of where it is up: as near below it as it can walk.
                return List.of(new NativeTaskCandidate(climb, "native_goto", Map.of("x", String.valueOf(at.getX()), "y", String.valueOf(at.getY()),
                        "z", String.valueOf(at.getZ()), "range", "2", "partial", "true", "sprint", "true")));
            }
            // At its foot: up a pillar of its own filler blocks, as a player climbs to someone on a ledge.
            var world = player.getServerWorld();
            if (player.isOnGround() && world.getBlockState(feet.up(2)).getCollisionShape(world, feet.up(2)).isEmpty()) {
                var inventory = player.getInventory();
                for (int slot = 0; slot < 36; slot++) {
                    var stack = inventory.getStack(slot);
                    if (stack.isEmpty() || !dev.kindred.core.match.PursuitBlock.FILLERS.contains(Registries.ITEM.getId(stack.getItem()).toString())) continue;
                    if (slot >= 9) {
                        int hotbar = 8;
                        for (int h = 0; h < 9; h++) if (inventory.getStack(h).isEmpty()) { hotbar = h; break; }
                        return List.of(new NativeTaskCandidate(climb, "native_swap", Map.of("source", String.valueOf(slot), "target", String.valueOf(hotbar))));
                    }
                    return List.of(new NativeTaskCandidate(climb, "native_pillar", Map.of("x", String.valueOf(feet.getX()), "y", String.valueOf(feet.getY()),
                            "z", String.valueOf(feet.getZ()), "slot", String.valueOf(slot))));
                }
            }
        }
        if (entry.campaign == null) entry.campaign = new PortalRunCampaign();
        var task = entry.campaign.buildRoute(body, at, p -> p.getSquaredDistance(at) <= 4, true, "Make a way to the runner");
        if (task.isEmpty()) return null;
        var t = task.get();
        UUID id = UUID.nameUUIDFromBytes(("way:" + entry.data.id() + ":" + t.skill() + ":" + new java.util.TreeMap<>(t.args()))
                .getBytes(StandardCharsets.UTF_8));
        entry.campaignTasks.clear();
        entry.campaignTasks.put(id, t);
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.URGENT, 98.0,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(candidate, t.skill(), t.args()));
    }

    /** A piece of a hunter's gear: the item, what it is made of, and how many of that. */
    private record GearPiece(net.minecraft.item.Item item, net.minecraft.item.Item material, int count) { }

    /**
     * The gear a hunter makes as the hunt goes on, best first (M-02b): a diamond sword, then diamond armour, from the
     * diamonds it holds; then iron armour, best protection for its iron first. Nothing is made that it already has as
     * good or better.
     */
    private static final List<GearPiece> HUNTER_GEAR = List.of(
            new GearPiece(Items.DIAMOND_SWORD, Items.DIAMOND, 2),
            new GearPiece(Items.DIAMOND_CHESTPLATE, Items.DIAMOND, 8), new GearPiece(Items.DIAMOND_LEGGINGS, Items.DIAMOND, 7),
            new GearPiece(Items.DIAMOND_HELMET, Items.DIAMOND, 5), new GearPiece(Items.DIAMOND_BOOTS, Items.DIAMOND, 4),
            new GearPiece(Items.IRON_CHESTPLATE, Items.IRON_INGOT, 8), new GearPiece(Items.IRON_LEGGINGS, Items.IRON_INGOT, 7),
            new GearPiece(Items.IRON_HELMET, Items.IRON_INGOT, 5), new GearPiece(Items.IRON_BOOTS, Items.IRON_INGOT, 4));

    /**
     * The next piece of gear a kitted hunter can make from the diamonds or iron ingots it holds, at a crafting table, or
     * null when it has the makings of none it lacks. A slot already holding as good or better is not made again, and a
     * diamond sword only where it has none. Three diamonds are kept back while it has no diamond pickaxe.
     */
    private List<NativeTaskCandidate> hunterArmour(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var inventory = player.getInventory();
        // Three diamonds kept for a diamond pickaxe while it has none: its goal's obsidian needs one.
        boolean pickaxe = inventory.count(Items.DIAMOND_PICKAXE) > 0 || inventory.count(Items.NETHERITE_PICKAXE) > 0;
        for (var piece : HUNTER_GEAR) {
            int kept = piece.material() == Items.DIAMOND && !pickaxe ? 3 : 0;
            if (inventory.count(piece.material()) < piece.count() + kept || inventory.count(piece.item()) > 0) continue;
            if (piece.item() instanceof net.minecraft.item.ArmorItem made) {
                var worn = player.getEquippedStack(player.getPreferredEquipmentSlot(new ItemStack(made)));
                if (worn.getItem() instanceof net.minecraft.item.ArmorItem armour && armour.getProtection() >= made.getProtection()) continue;
            } else if (inventory.count(Items.NETHERITE_SWORD) > 0) {
                continue;
            }
            if (entry.campaign == null) entry.campaign = new PortalRunCampaign();
            var task = entry.campaign.craftAtTable(body, net.minecraft.registry.Registries.ITEM.getId(piece.item()).getPath());
            if (task.isEmpty()) return null;
            var t = task.get();
            UUID id = UUID.nameUUIDFromBytes(("gear:" + entry.data.id() + ":" + t.skill() + ":" + new java.util.TreeMap<>(t.args()))
                    .getBytes(StandardCharsets.UTF_8));
            entry.campaignTasks.clear();
            entry.campaignTasks.put(id, t);
            var candidate = new dev.kindred.core.TaskPreferences.Candidate(id, dev.kindred.core.TaskPreferences.Priority.PROJECT, 91.0,
                    dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
            return List.of(new NativeTaskCandidate(candidate, t.skill(), t.args()));
        }
        return null;
    }

    /** How many times each runner has moved off from a hunter in sight, for its log and fixtures. */
    private final Map<UUID, Integer> evasions = new HashMap<>();
    private final Map<UUID, BlockPos> evadingTo = new HashMap<>();

    int evasions(UUID player) {
        requireThread();
        return evasions.getOrDefault(player, 0);
    }

    /**
     * How near a hunter a runner sees before it moves off, how near it is caught and fights back, and how far off a
     * home it still keeps its hunters from.
     */
    private static final double EVADE = 20, CAUGHT = 3.2, HOME_KEPT = 160;
    /** How much further than {@link #EVADE} a runner already moving off keeps going before it counts itself clear. */
    private static final double CLEAR_MARGIN = 8;

    /**
     * The home a chased player keeps its pursuers from (M-02c): its first base in this world, else the bed its spawn
     * is set by; none when it has neither here.
     */
    private static BlockPos homeToKeep(Entry entry, ServerPlayerEntity player) {
        var world = player.getServerWorld();
        String dimension = world.getRegistryKey().getValue().toString();
        if (entry.bases != null) {
            for (var base : entry.bases.built) {
                if (!base.dimension().equals(dimension)) continue;
                var span = footprint(base);
                return new BlockPos((span.minX() + span.maxX()) / 2, base.y(), (span.minZ() + span.maxZ()) / 2);
            }
        }
        var spawn = player.getSpawnPointPosition();
        return spawn != null && player.getSpawnPointDimension() == world.getRegistryKey() ? spawn : null;
    }

    /**
     * An AI runner in a running manhunt, a hunter in sight (M-02b): it keeps its distance, at a run, away from the
     * nearest hunter it can see but never toward its home while another way is open (M-02c), and fights only once
     * caught. Running weighs more than eating, so it eats once clear, at a safe distance. Null when no hunter is in
     * sight, or the player runs from nobody; its goal goes on.
     */
    private List<NativeTaskCandidate> evadeCandidates(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var match = matches.running(player.getUuid())
                .filter(m -> m.mode() == dev.kindred.core.match.MatchRegistry.Mode.MANHUNT && m.runners().contains(player.getUuid())).orElse(null);
        if (match == null) return null;
        ServerPlayerEntity hunter = null;
        // Once moving off, it keeps going until well clear, not just past the edge where it started: its goal would walk
        // it straight back toward a hunter it has only just left (found in the head start fixture, M-02b).
        double reach = evadingTo.containsKey(player.getUuid()) ? EVADE + CLEAR_MARGIN : EVADE;
        for (UUID other : match.joined()) {
            if (!match.hunter(other) || !match.playing(other)) continue;
            var seen = server.getPlayerManager().getPlayer(other);
            if (seen == null || !seen.isAlive() || seen.getServerWorld() != player.getServerWorld() || player.squaredDistanceTo(seen) > reach * reach
                    || !player.canSee(seen)) continue;
            if (hunter == null || player.squaredDistanceTo(seen) < player.squaredDistanceTo(hunter)) hunter = seen;
        }
        if (hunter == null) {
            if (evadingTo.remove(player.getUuid()) != null) KindredMod.LOGGER.info("{} is clear of its hunters", player.getName().getString());
            return null;
        }
        UUID taskId = UUID.nameUUIDFromBytes(("evade:" + match.id() + ":" + player.getUuid()).getBytes(StandardCharsets.UTF_8));
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(taskId, dev.kindred.core.TaskPreferences.Priority.URGENT, 98.0,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        if (player.distanceTo(hunter) <= CAUGHT && matches.mayAttack(player.getUuid(), hunter.getUuid())) {
            // Caught: no getting away from a hunter at arm's length, so it fights. Not while the match lets nobody strike
            // (the runners' head start): the hunter is held, so it runs (found in a live hunt, M-02b).
            int slot = Weapons.choose(player, NativePlayerBody.believedHealth(player, hunter), true).map(Weapons.Held::slot).orElse(-1);
            return List.of(new NativeTaskCandidate(candidate, "native_fight", Map.of("target", hunter.getUuid().toString(), "slot", String.valueOf(slot))));
        }
        // Blocking pursuit (M-02b): going through a way one block wide with the hunter coming along it, the gap behind
        // is shut with two of its own filler blocks before it runs on.
        var shut = shutBehind(body, hunter, candidate);
        if (shut != null) return shut;
        BlockPos target = awayFrom(entry, player, hunter);
        var last = evadingTo.get(player.getUuid());
        if (last == null || last.getSquaredDistance(target) > 16) {
            evadingTo.put(player.getUuid(), target.toImmutable());
            evasions.merge(player.getUuid(), 1, Integer::sum);
            KindredMod.LOGGER.info("{} keeps away from {}, {} blocks off: toward {}", player.getName().getString(), hunter.getName().getString(),
                    String.format("%.1f", player.distanceTo(hunter)), target.toShortString());
        }
        return List.of(new NativeTaskCandidate(candidate, "native_goto", Map.of("x", String.valueOf(target.getX()), "y", String.valueOf(target.getY()),
                "z", String.valueOf(target.getZ()), "range", "3", "partial", "true", "sprint", "true")));
    }

    /** How many cells each runner has chosen to shut behind it, for its log (M-02b). */
    private final Map<UUID, Integer> shutWays = new HashMap<>();
    /** The cell each runner last chose to shut, so a choice made again each look is logged and counted once. */
    private final Map<UUID, BlockPos> shutting = new HashMap<>();

    int shutWays(UUID player) {
        requireThread();
        return shutWays.getOrDefault(player, 0);
    }

    /**
     * The next block a fleeing player puts into the one-wide gap behind it, toward {@code threat} (M-02b), as
     * {@link dev.kindred.core.match.PursuitBlock} picks the gap: a filler block of its own from its hotbar, readied there
     * first if it is further in. Null when the way behind is not one wide, the threat is not coming along it, it has no
     * filler, or the world's edit policy does not let it place there.
     */
    private List<NativeTaskCandidate> shutBehind(NativePlayerBody body, ServerPlayerEntity threat, dev.kindred.core.TaskPreferences.Candidate candidate) {
        var player = body.entity();
        var world = player.getServerWorld();
        if (!player.isOnGround() || !worldEditsEnabled()) return null;
        BlockPos feet = player.getBlockPos();
        var ground = new dev.kindred.core.match.PursuitBlock.Ground() {
            @Override public boolean open(dev.kindred.core.construction.Pos cell) {
                BlockPos at = new BlockPos(cell.x(), cell.y(), cell.z());
                var state = world.getBlockState(at);
                return state.getCollisionShape(world, at).isEmpty() && state.getFluidState().isEmpty();
            }
            @Override public boolean solid(dev.kindred.core.construction.Pos cell) {
                BlockPos at = new BlockPos(cell.x(), cell.y(), cell.z());
                return world.getBlockState(at).isSolidBlock(world, at);
            }
        };
        var cells = dev.kindred.core.match.PursuitBlock.behind(new dev.kindred.core.construction.Pos(feet.getX(), feet.getY(), feet.getZ()),
                threat.getX() - player.getX(), threat.getZ() - player.getZ(), ground);
        if (cells.isEmpty()) return null;
        // The gap's first open cell: the lower one, then the one above it.
        var cell = cells.stream().filter(ground::open).findFirst().orElse(null);
        if (cell == null) return null;
        BlockPos at = new BlockPos(cell.x(), cell.y(), cell.z());
        if (!mayEditAt(player, at)) return null;
        int slot = -1;
        var inventory = player.getInventory();
        for (int s = 0; s < 36 && slot < 0; s++) {
            var stack = inventory.getStack(s);
            if (!stack.isEmpty() && dev.kindred.core.match.PursuitBlock.FILLERS.contains(net.minecraft.registry.Registries.ITEM.getId(stack.getItem()).toString())) slot = s;
        }
        if (slot < 0) return null;
        if (slot >= 9) {
            int hotbar = 8;
            for (int h = 0; h < 9; h++) if (inventory.getStack(h).isEmpty()) { hotbar = h; break; }
            return List.of(new NativeTaskCandidate(candidate, "native_swap", Map.of("source", String.valueOf(slot), "target", String.valueOf(hotbar))));
        }
        if (!at.equals(shutting.put(player.getUuid(), at.toImmutable()))) {
            shutWays.merge(player.getUuid(), 1, Integer::sum);
            KindredMod.LOGGER.info("{} shuts the way behind it from {}: a block at {}", player.getName().getString(), threat.getName().getString(), at.toShortString());
        }
        return List.of(new NativeTaskCandidate(candidate, "native_place", Map.of("x", String.valueOf(at.getX()), "y", String.valueOf(at.getY()),
                "z", String.valueOf(at.getZ()), "slot", String.valueOf(slot))));
    }

    /**
     * Where it runs to from {@code threat}: sixteen blocks away from it, or at an angle where the way straight off is
     * shut, never toward its own home, its base or its bed while another way is open (M-02c); straight away when no way
     * is open.
     */
    private BlockPos awayFrom(Entry entry, ServerPlayerEntity player, ServerPlayerEntity threat) {
        BlockPos open = openWayFrom(entry, player, threat);
        if (open != null) return open;
        Vec3d away = awayDirection(player, threat);
        BlockPos feet = player.getBlockPos();
        return BlockPos.ofFloored(feet.getX() + 0.5 + away.x * 16, feet.getY(), feet.getZ() + 0.5 + away.z * 16);
    }

    private static Vec3d awayDirection(ServerPlayerEntity player, ServerPlayerEntity threat) {
        Vec3d away = player.getPos().subtract(threat.getPos()).multiply(1, 0, 1);
        if (away.lengthSquared() < 1e-4) away = new Vec3d(1, 0, 0);
        return away.normalize();
    }

    /** A way off from {@code threat} with ground to stand on, as {@link #awayFrom} picks it; null when none is open. */
    private BlockPos openWayFrom(Entry entry, ServerPlayerEntity player, ServerPlayerEntity threat) {
        Vec3d away = awayDirection(player, threat);
        var navigator = new NativeNavigator(player.getServerWorld());
        BlockPos feet = player.getBlockPos();
        // Never toward its own home, its base or the bed it sleeps in: a chased player does not lead its pursuers there
        // (M-02c). Only when every way off is toward home does it run that way all the same.
        BlockPos home = homeToKeep(entry, player);
        double homeX = home == null ? 0 : home.getX() + 0.5 - player.getX(), homeZ = home == null ? 0 : home.getZ() + 0.5 - player.getZ();
        if (homeX * homeX + homeZ * homeZ > HOME_KEPT * HOME_KEPT) homeX = homeZ = 0;
        for (double turn : dev.kindred.core.match.EvasionCourse.turns(away.x, away.z, homeX, homeZ)) {
            Vec3d way = away.rotateY((float) Math.toRadians(turn));
            BlockPos at = BlockPos.ofFloored(feet.getX() + 0.5 + way.x * 16, feet.getY(), feet.getZ() + 0.5 + way.z * 16);
            for (int dy : new int[] {0, 1, -1, 2, -2}) {
                if (navigator.standable(at.up(dy))) return at.up(dy).toImmutable();
            }
        }
        return null;
    }

    /**
     * The build being voted on (M-04): when it changes, everyone in the round is told whose it is and where to stand, and
     * each human voter is offered its scores; an AI voter standing on its marked spot with the build in sight scores what
     * it sees there. A build is voted on only while it is shown.
     */
    private void showBuild(dev.kindred.core.match.MatchRegistry.Match match, dev.kindred.core.match.BuildBattle battle) {
        var arena = arenas.get(match.id());
        var showing = dev.kindred.core.match.MatchRegistry.showing(match, server.getTicks()).orElse(null);
        if (arena == null || showing == null) return;
        var spot = arena.spots().get(showing);
        if (!showing.equals(showingNow.put(match.id(), showing))) {
            String name = playerName(showing);
            KindredMod.LOGGER.info("Build battle {}: showing {}'s build", dev.kindred.core.match.MatchRegistry.shortId(match.id()), name);
            for (UUID voter : match.invited()) {
                var player = server.getPlayerManager().getPlayer(voter);
                if (player == null) continue;
                presenter.show(voter, new dev.kindred.core.match.MatchPresentation.Title(name + "'s build",
                        voter.equals(showing) ? "Everyone else votes on it" : "Stand on the gold mark and vote", dev.kindred.core.match.MatchPresentation.Cue.COUNT));
                if (voter.equals(showing) || entryForPlayer(voter) != null) continue;
                var line = Text.literal("Vote on " + name + "'s build (stand on the gold mark at " + spot.x() + " " + spot.y() + " " + spot.z() + "): ");
                for (int score = 1; score <= 5; score++) {
                    String vote = "/aiplayer match vote " + name + " " + score;
                    line.append(Text.literal("[" + score + "] ").styled(style -> style.withColor(net.minecraft.util.Formatting.GREEN)
                            .withClickEvent(new net.minecraft.text.ClickEvent(net.minecraft.text.ClickEvent.Action.RUN_COMMAND, vote))));
                }
                player.sendMessage(line, false);
            }
        }
        var plot = battle.plot(showing).orElse(null);
        if (plot == null) return;
        for (UUID voter : match.joined()) {
            if (voter.equals(showing) || !match.playing(voter) || battle.voted(voter, showing)) continue;
            Entry entry = entryForPlayer(voter);
            var player = server.getPlayerManager().getPlayer(voter);
            if (entry == null || player == null) continue;
            if (!atSpot(player, spot) || !seesPlot(player, plot)) continue;
            int score = dev.kindred.core.match.BuildBattle.judge(plotBlocks(player.getServerWorld(), plot), battle.theme());
            battle.vote(voter, showing, score);
            toured.computeIfAbsent(match.id(), id -> new ArrayList<>()).add(new TourVote(voter, showing, player.getBlockPos().toImmutable(), score));
            KindredMod.LOGGER.info("Build battle {}: {} gives {}'s build {}, seen from its spot", dev.kindred.core.match.MatchRegistry.shortId(match.id()),
                    playerName(voter), playerName(showing), score);
        }
    }

    /** An AI voter's vote in a round's tour: who, on whose build, where it stood, the score. For fixtures. */
    record TourVote(UUID voter, UUID builder, BlockPos stood, int score) { }
    private final Map<UUID, List<TourVote>> toured = new HashMap<>();

    List<TourVote> tourVotesForTest(UUID matchId) {
        requireThread();
        return List.copyOf(toured.getOrDefault(matchId, List.of()));
    }

    /** AI voters waiting for their last action to settle before they go into adventure for the vote (M-04). */
    private final Set<UUID> toAdventure = new java.util.LinkedHashSet<>();

    /**
     * Each tick: an AI voter whose last action has settled goes into adventure for the vote, walking only. One whose round
     * has moved on is let go.
     */
    private void settleVoters() {
        for (var it = toAdventure.iterator(); it.hasNext(); ) {
            Entry entry = entries.get(it.next());
            var player = entry == null || entry.nativeBody == null ? null : entry.nativeBody.entity();
            var match = player == null ? null : matches.active(player.getUuid()).filter(m -> m.mode() == dev.kindred.core.match.MatchRegistry.Mode.BUILDER)
                    .orElse(null);
            if (match == null || match.state() != dev.kindred.core.match.MatchRegistry.State.VOTING) {
                it.remove();
                continue;
            }
            if (entry.runner != null && runnerBusy(entry) || entry.nativeActionPending || !entry.nativeActionFlush.isDone()
                    || !entry.activityFlush.isDone()) continue;
            it.remove();
            entry.nativeBody.allowCreative(false);
            entry.nativeBody.allowAdventure(true);
            player.getInventory().clear();
            player.changeGameMode(net.minecraft.world.GameMode.ADVENTURE);
            ArenaSnapshots.building(player.getUuid(), false);
            entry.cachedRoutineCandidates = List.of();
            entry.routineRefreshPending = true;
        }
    }

    /** Standing on (or by) a viewing spot. */
    private static boolean atSpot(ServerPlayerEntity player, dev.kindred.core.construction.Pos spot) {
        double dx = player.getX() - (spot.x() + 0.5), dz = player.getZ() - (spot.z() + 0.5);
        return dx * dx + dz * dz <= 2.5 * 2.5 && Math.abs(player.getY() - spot.y()) <= 1.5;
    }

    /** Whether a player sees into a plot from where it stands: its line of sight to the plot's middle ends on the plot. */
    private static boolean seesPlot(ServerPlayerEntity player, dev.kindred.core.match.BuildBattle.Plot plot) {
        var o = plot.origin();
        var middle = new Vec3d(o.x() + dev.kindred.core.match.BuildBattle.PLOT / 2.0, o.y() + 1.5, o.z() + dev.kindred.core.match.BuildBattle.PLOT / 2.0);
        var hit = player.getServerWorld().raycast(new net.minecraft.world.RaycastContext(player.getEyePos(), middle,
                net.minecraft.world.RaycastContext.ShapeType.COLLIDER, net.minecraft.world.RaycastContext.FluidHandling.NONE, player));
        if (hit.getType() == net.minecraft.util.hit.HitResult.Type.MISS) return true;
        var at = hit.getBlockPos();
        return plot.contains(new dev.kindred.core.construction.Pos(at.getX(), at.getY(), at.getZ())) || at.getY() == o.y()
                && at.getX() >= o.x() && at.getX() < o.x() + dev.kindred.core.match.BuildBattle.PLOT
                && at.getZ() >= o.z() && at.getZ() < o.z() + dev.kindred.core.match.BuildBattle.PLOT;
    }

    /**
     * An AI voter in a build battle's vote (M-04): to the marked spot in front of the build being shown. Null outside a
     * vote; none when it is there, or the build shown is its own.
     */
    private List<NativeTaskCandidate> voteCandidates(Entry entry, NativePlayerBody body) {
        var player = body.entity();
        var match = matches.active(player.getUuid()).filter(m -> m.mode() == dev.kindred.core.match.MatchRegistry.Mode.BUILDER
                && m.state() == dev.kindred.core.match.MatchRegistry.State.VOTING).orElse(null);
        if (match == null) return null;
        var arena = arenas.get(match.id());
        var showing = dev.kindred.core.match.MatchRegistry.showing(match, server.getTicks()).orElse(null);
        if (arena == null || showing == null) return List.of();
        var spot = arena.spots().get(showing);
        // Its own build shown: it stands back by the spot all the same, as a builder does.
        if (atSpot(player, spot)) return List.of();
        UUID taskId = UUID.nameUUIDFromBytes(("vote:" + match.id() + ":" + player.getUuid() + ":" + showing).getBytes(StandardCharsets.UTF_8));
        var candidate = new dev.kindred.core.TaskPreferences.Candidate(taskId, dev.kindred.core.TaskPreferences.Priority.URGENT, 97.0,
                dev.kindred.core.TaskPreferences.Affinities.none(), new dev.kindred.core.TaskPreferences.Eligibility(true, true, true, true));
        return List.of(new NativeTaskCandidate(candidate, "native_goto", Map.of("x", String.valueOf(spot.x()), "y", String.valueOf(spot.y()),
                "z", String.valueOf(spot.z()), "range", "1", "partial", "true", "sprint", "true")));
    }

    /** Once a second: each running race's runners checked for the splits vanilla has given them since. */
    private void pollRaces() {
        for (var match : matches.list()) {
            if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.SPEEDRUN || match.state() != dev.kindred.core.match.MatchRegistry.State.RUNNING) continue;
            var splits = races.get(match.id());
            if (splits == null) continue;
            for (UUID runner : match.joined()) {
                if (!match.playing(runner)) continue;
                var player = server.getPlayerManager().getPlayer(runner);
                if (player == null) continue;
                for (var split : dev.kindred.core.match.SpeedrunSplits.ANY_PERCENT) {
                    if (!reached(player, split)) continue;
                    var reached = splits.reach(runner, split, server.getTicks()).orElse(null);
                    if (reached == null) continue;
                    presenter.split(match, reached, this::playerName);
                    KindredMod.LOGGER.info("Speedrun {}: {} {} at {}", dev.kindred.core.match.MatchRegistry.shortId(match.id()), playerName(runner),
                            split.label(), dev.kindred.core.match.SpeedrunSplits.time(reached.ticks()));
                    if (reached.finish()) {
                        matches.finished(runner).ifPresent(this::announce);
                        return;
                    }
                }
            }
        }
    }

    /** How far the leading runner of a race is, as a share of the splits; a whole bar for anything else. */
    private float raceProgress(UUID matchId) {
        var splits = races.get(matchId);
        var match = matches.get(matchId).orElse(null);
        if (splits == null || match == null) return 1f;
        int most = 0;
        for (UUID runner : match.joined()) most = Math.max(most, splits.of(runner).size());
        return most / (float) dev.kindred.core.match.SpeedrunSplits.ANY_PERCENT.size();
    }

    /** A race's splits as reached so far, for a fixture or a status line. */
    List<dev.kindred.core.match.SpeedrunSplits.Reached> raceSplits(UUID matchId, UUID runner) {
        requireThread();
        var splits = races.get(matchId);
        return splits == null ? List.of() : splits.of(runner);
    }

    /** A player's word on its match's sidebar: a racer's splits so far. */
    private String standing(dev.kindred.core.match.MatchRegistry.Match match, UUID player) {
        if (match.mode() != dev.kindred.core.match.MatchRegistry.Mode.SPEEDRUN && !(match.mode() == dev.kindred.core.match.MatchRegistry.Mode.MANHUNT
                && match.runners().contains(player))) return "";
        int splits = raceSplits(match.id(), player).size();
        return splits == 0 ? "" : splits + (splits == 1 ? " split" : " splits");
    }

    /** The player running the command joins a match it was invited to. Only a player can join, and only for itself. */
    int joinMatch(ServerCommandSource source, UUID matchId) {
        requireThread();
        if (!(source.getEntity() instanceof ServerPlayerEntity player)) return reject(source, "Only a player can join a match, for itself.");
        var result = matches.join(matchId, player.getUuid());
        if (!result.accepted()) return reject(source, result.reason());
        feedback(source, "Joined the " + result.match().orElseThrow().mode().label().toLowerCase(java.util.Locale.ROOT) + ".");
        return 1;
    }

    /** Starts a match whose every invited player has joined: an operator, or a joined player. */
    int startMatch(ServerCommandSource source, UUID matchId) {
        requireThread();
        var match = matches.get(matchId).orElse(null);
        if (match == null) return reject(source, "No such match.");
        boolean participant = source.getEntity() instanceof ServerPlayerEntity player && match.participant(player.getUuid());
        if (!participant && !source.hasPermissionLevel(2)) return reject(source, "Only an operator or a player in the match can start it.");
        if (match.mode().pvp && !server.isPvpEnabled()) return reject(source, "PvP is off on this server (pvp=false in server.properties); no duel can be fought.");
        var result = matches.start(matchId, server.getTicks());
        if (!result.accepted()) return reject(source, result.reason());
        announce(result.match().orElseThrow());
        return 1;
    }

    /** Stops a match: an operator stops it outright; a player in it forfeits. */
    int stopMatch(ServerCommandSource source, UUID matchId) {
        requireThread();
        var match = matches.get(matchId).orElse(null);
        if (match == null) return reject(source, "No such match.");
        dev.kindred.core.match.MatchRegistry.Result result;
        if (source.hasPermissionLevel(2)) {
            result = matches.stop(matchId);
        } else if (source.getEntity() instanceof ServerPlayerEntity player && match.participant(player.getUuid())) {
            result = matches.leave(matchId, player.getUuid());
        } else {
            return reject(source, "Only an operator or a player in the match can stop it.");
        }
        if (!result.accepted()) return reject(source, result.reason());
        announce(result.match().orElseThrow());
        return 1;
    }

    /**
     * A player died, a person or an AI player alike: the death written to the World Record (F-31) with where, how and
     * by whom, then {@link #playerFell}.
     */
    void playerDied(net.minecraft.server.network.ServerPlayerEntity player, net.minecraft.entity.damage.DamageSource source) {
        requireThread();
        // This runtime's own AI players are recorded by their own death hook (onNativeDeath), once.
        if (entryForPlayer(player.getUuid()) == null) recordDeath(player, source);
        playerFell(player.getUuid());
    }

    /** A death written to the World Record (F-31): who, where, the cause, and the killer when a player. */
    private void recordDeath(net.minecraft.server.network.ServerPlayerEntity player, net.minecraft.entity.damage.DamageSource source) {
        UUID killer = source != null && source.getAttacker() instanceof net.minecraft.server.network.ServerPlayerEntity attacker && attacker != player ? attacker.getUuid() : null;
        var data = new java.util.LinkedHashMap<String, String>();
        data.put("cause", source == null ? "unknown" : source.getName());
        data.put("killer", killer == null ? "" : killer.toString());
        BlockPos at = player.getBlockPos();
        record(dev.kindred.core.record.WorldEvent.recorded(server.getTicks(), System.currentTimeMillis(), player.getServerWorld().getRegistryKey().getValue().toString(),
                dev.kindred.core.record.DeathLedger.DEATH, player.getUuid(), player.getGameProfile().getName(), at.getX() + "," + at.getY() + "," + at.getZ(), data));
        // In a faction world, the power it costs when it qualifies (M-06c), the same for people and AI players.
        if (factionsWorld()) {
            String why = factions.died(player, killer);
            KindredMod.LOGGER.info("{} died in a faction world: {}", player.getGameProfile().getName(), why);
        }
    }

    /** Once a game day, at night: the ledgers checked against the Record (F-31). */
    static final int LEDGER_CHECK_TICKS = 24_000;
    /** How old a settled action's last event is before its history is folded: three game days of real time at 20 ticks a second. */
    static final long ACTION_FOLD_AGE_MS = 3L * 24_000 / 20 * 1_000;
    /** The most actions one fold takes, so a pass keeps the writer busy for a bounded time. */
    static final int ACTION_FOLD_MAX = 5_000;
    /** The most passes after one check: 50,000 actions, about 3.6 s of the writer's time, in jobs of about 0.36 s each. */
    static final int ACTION_FOLD_PASSES = 10;

    /**
     * The agreement check (F-31): every ledger kept here, and the action ledger's own table, against the same rebuilt from
     * the World Record alone up to the last event the ledgers have folded in, read and folded off the server thread. Each check
     * is itself an event ({@code ledger_check}); a disagreement is logged as an error for an operator, never repaired.
     */
    CompletableFuture<Boolean> checkLedgers() {
        requireThread();
        SqliteCompanionStore database = store;
        if (database == null) return CompletableFuture.completedFuture(false);
        // The ledgers as they stand against the Record up to the last event they have folded in.
        dev.kindred.core.record.Ledgers kept = ledgers;
        long through = ledgersThrough;
        var result = new CompletableFuture<Boolean>();
        // F-31f: the action ledger read off the writer, from one snapshot, streamed; the writer goes on writing meanwhile.
        database.allWorldEvents(dev.kindred.core.record.Ledgers.kinds())
                .thenCombine(database.checkActionLedgerFromSnapshot(), (events, actions) -> {
                    var upTo = events.stream().filter(event -> event.id() <= through).toList();
                    return java.util.Map.entry(new ArrayList<dev.kindred.core.record.Ledger.Agreement<?>>(kept.check(upTo)), actions);
                }).whenComplete((both, failure) -> handBack(() -> {
                    if (failure != null) {
                        Throwable cause = failure instanceof java.util.concurrent.CompletionException && failure.getCause() != null ? failure.getCause() : failure;
                        // Stopped with the server: no verdict, and none recorded; the next check reads it all again.
                        if (cause instanceof java.util.concurrent.CancellationException) KindredMod.LOGGER.info("World Record check stopped before it was done; nothing reported");
                        else KindredMod.LOGGER.error("World Record check could not run", failure);
                        result.complete(false);
                        return;
                    }
                    var checks = both.getKey();
                    var actions = both.getValue();
                    boolean agree = checks.stream().allMatch(dev.kindred.core.record.Ledger.Agreement::agrees) && actions.agrees();
                    var data = new java.util.LinkedHashMap<String, String>();
                    for (var check : checks) data.put(check.ledger(), check.agrees() ? "agrees" : "differs");
                    data.put(dev.kindred.core.record.ActionLedgerView.INSTANCE.name(), actions.agrees() ? "agrees" : actions.differing() > 0 ? "differs" : "not checked");
                    for (var check : checks) if (!check.agrees()) KindredMod.LOGGER.error("Ledger {} differs from the World Record: kept {} but the Record gives {}",
                            check.ledger(), check.kept(), check.fromRecord());
                    if (actions.differing() > 0) KindredMod.LOGGER.error("Ledger {} differs from the World Record in {} of {} actions: {}",
                            dev.kindred.core.record.ActionLedgerView.INSTANCE.name(), actions.differing(), actions.rows(), actions.differences());
                    if (actions.unchecked() > 0) KindredMod.LOGGER.error("Ledger {} not checked against the World Record: {} actions named other than as an id is written: {}",
                            dev.kindred.core.record.ActionLedgerView.INSTANCE.name(), actions.unchecked(), actions.notChecked());
                    if (running) record(dev.kindred.core.record.WorldEvent.recorded(server.getTicks(), System.currentTimeMillis(), "", dev.kindred.core.record.Ledgers.CHECK, null,
                            agree ? "agrees" : "differs", "", data));
                    // The action fold (F-31): once the Record and the ledgers agree, settled action history older than
                    // three game days compacted on the writer, a batch at a time, never on the tick.
                    if (agree && running) foldActions(database, System.currentTimeMillis() - ACTION_FOLD_AGE_MS, ACTION_FOLD_PASSES, new long[3]);
                    result.complete(agree);
                }));
        return result;
    }

    /**
     * The action fold's passes (F-31): each a separate job on the writer, so other writes run between them; another
     * while the last took its full share, at most {@code passes}; the totals logged once at the end.
     */
    private static void foldActions(SqliteCompanionStore database, long olderThanMs, int passes, long[] totals) {
        database.foldSettledActions(olderThanMs, ACTION_FOLD_MAX).whenComplete((fold, unfolded) -> {
            if (unfolded != null) {
                KindredMod.LOGGER.warn("Action fold could not run: {}", unfolded.toString());
                return;
            }
            totals[0] += fold.actions();
            totals[1] += fold.eventsRemoved();
            totals[2] += fold.millis();
            if (fold.actions() == ACTION_FOLD_MAX && passes > 1) {
                foldActions(database, olderThanMs, passes - 1, totals);
                return;
            }
            if (totals[0] > 0) KindredMod.LOGGER.info("Kindred action fold: {} settled actions, {} events, folded in {} ms on the writer",
                    totals[0], totals[1], totals[2]);
        });
    }

    /** Each match changed since the last flush written to the World Record as it now stands (F-31). */
    private void flushMatches() {
        var changed = matches.drainChanges();
        if (changed.isEmpty()) return;
        long tick = server.getTicks(), now = System.currentTimeMillis();
        record(changed.stream().map(stored -> dev.kindred.core.record.MatchLedger.event(tick, now, "", stored)).toList());
    }

    /** The Chronicle (F-33), for fixtures: its pages and counts, and a day's pages written now. */
    ChronicleKeeper chronicleForFixtures() { return chronicle; }

    /** The keeper's side: the Record, the AI players with their bodies' ids, the strategist's bridge. */
    private final class ChronicleHost implements ChronicleKeeper.Host {
        @Override public java.util.concurrent.CompletableFuture<List<dev.kindred.core.record.WorldEvent>> events(java.util.Set<String> kinds, long afterId, int limit) {
            SqliteCompanionStore database = store;
            return database == null ? java.util.concurrent.CompletableFuture.completedFuture(List.of()) : database.worldEvents(kinds, afterId, limit);
        }

        @Override public void record(dev.kindred.core.record.WorldEvent event) { PlayerRuntime.this.record(event); }

        @Override public List<ChronicleKeeper.Player> players() {
            var out = new ArrayList<ChronicleKeeper.Player>();
            for (Entry entry : entries.values()) {
                if (entry.data == null) continue;
                var actors = new java.util.HashSet<UUID>();
                actors.add(entry.data.id());
                if (entry.nativeBody != null && entry.nativeBody.connected()) actors.add(entry.nativeBody.entity().getUuid());
                out.add(new ChronicleKeeper.Player(entry.data.id(), entry.data.displayName(), actors, factionOf.apply(entry.data.id())));
            }
            return out;
        }

        @Override public long tick() { return server.getTicks(); }

        @Override public StrategistBridge bridge() { return memory; }

        @Override public net.minecraft.server.MinecraftServer server() { return server; }
    }

    /**
     * F-34: events written to the World Record, then a message that rests on them sent on the Wire, citing exactly the
     * ids the ordered writer gave them, on this thread. Never before they are written, and on a failed write nothing is
     * said: a message never cites an event the Record does not hold. {@code tell} makes the message from those ids;
     * null for none. What the Wire did with it, or null when nothing was sent, goes to {@code sent}.
     */
    void recordAndTell(List<dev.kindred.core.record.WorldEvent> drafts, java.util.function.Function<List<Long>, dev.kindred.core.wire.Message> tell,
                       java.util.function.Consumer<dev.kindred.core.wire.Delivery> sent) {
        recordAndTellAll(drafts, ids -> {
            var message = tell.apply(ids);
            return message == null ? List.of() : List.of(message);
        }, sent == null ? null : deliveries -> sent.accept(deliveries.isEmpty() ? null : deliveries.getFirst()));
    }

    /**
     * As {@link #recordAndTell}, with every message {@code tell} makes from the written ids sent in order (M-06e's
     * capture tells each side's faction, both resting on the same events); what the Wire did with each goes to
     * {@code sent}, empty when nothing was sent.
     */
    void recordAndTellAll(List<dev.kindred.core.record.WorldEvent> drafts,
                          java.util.function.Function<List<Long>, List<dev.kindred.core.wire.Message>> tell,
                          java.util.function.Consumer<List<dev.kindred.core.wire.Delivery>> sent) {
        requireThread();
        java.util.function.Consumer<List<dev.kindred.core.wire.Delivery>> done = sent == null ? d -> { } : sent;
        // The stop barrier stops the tell, never the events: what was decided is the Record's (its ordered writer, which
        // the stop waits on), so an audit never finds a claim with no event; only the message resting on it goes unsent.
        // Stopped (the Record closed), nothing is decided to write: no act runs once the runtime has stopped.
        if (!running) {
            lateWritesRefused++;
            KindredMod.LOGGER.warn("Kindred stopped: {} event(s) not written and nothing told: the Record is closed", drafts.size());
            done.accept(List.of());
            return;
        }
        if (stopping) {
            lateTellsRefused++;
            KindredMod.LOGGER.warn("Kindred stopping: {} event(s) written, nothing told of them", drafts.size());
            record(drafts);
            done.accept(List.of());
            return;
        }
        SqliteCompanionStore database = store;
        if (database == null || drafts.isEmpty()) {
            KindredMod.LOGGER.warn("Nothing recorded, so nothing told: {}", database == null ? "World Record not open" : "no events");
            done.accept(List.of());
            return;
        }
        long epoch = stopEpoch;
        record(drafts);
        @SuppressWarnings("unchecked") var write = (CompletableFuture<List<dev.kindred.core.record.WorldEvent>>) recordFlush;
        // Told later, never within this call: a stop made next by its caller drops the tell, however fast the write.
        write.whenComplete((written, failure) -> handBackLater(() -> {
            // A write begun before the stop may land; what would be told of it is dropped, and its caller not called back.
            if (epoch != stopEpoch) {
                lateCallbacksDropped++;
                KindredMod.LOGGER.warn("Kindred stopped: a tell resting on {} event(s) dropped after the stop", drafts.size());
                return;
            }
            if (failure != null || written == null || !running) {
                done.accept(List.of());
                return;
            }
            var deliveries = new ArrayList<dev.kindred.core.wire.Delivery>();
            for (var message : tell.apply(written.stream().map(dev.kindred.core.record.WorldEvent::id).toList())) {
                if (message != null) deliveries.add(wire.send(message));
            }
            done.accept(List.copyOf(deliveries));
        }));
    }

    /** Events written to the World Record, then {@code written} or {@code failed} run on this thread. */
    void recordThen(List<dev.kindred.core.record.WorldEvent> drafts, Runnable written, java.util.function.Consumer<Throwable> failed) {
        requireThread();
        // Stop revokes synchronously and invalidates late callbacks: a write asked for after the stop (a callback of
        // work begun before it) is not tried, and neither callback runs. What it would have finished stays unfinished in
        // the Record, reported for an operator at the next start, never replayed (M-06h's intent and delivery rules).
        if (!running || stopping) {
            lateWritesRefused++;
            KindredMod.LOGGER.warn("Kindred stopped: {} event(s) not written, their work left for reconciliation: {}", drafts.size(),
                    drafts.isEmpty() ? "" : drafts.getFirst().kind());
            return;
        }
        if (store == null) {
            failed.accept(new IllegalStateException("World Record not open"));
            return;
        }
        long epoch = stopEpoch;
        record(drafts);
        var write = recordFlush;
        write.whenComplete((ignored, failure) -> handBack(() -> {
            if (epoch != stopEpoch) {
                lateCallbacksDropped++;
                KindredMod.LOGGER.warn("Kindred stopped: a callback of {} event(s) dropped after the stop", drafts.size());
                return;
            }
            if (failure == null) written.run(); else failed.accept(failure);
        }));
    }

    /** Bumped as each stop begins: a write-then-callback begun under an earlier epoch drops its callback. */
    private long stopEpoch;
    /** From the first line of stop() until the next start(): no write-then-callback is begun. */
    private boolean stopping;
    /** Writes asked for after the stop and not tried, and callbacks dropped after it, for fixtures. */
    private int lateWritesRefused, lateCallbacksDropped, lateTellsRefused;

    /** Test-only and read-only: {writes refused after the stop, callbacks dropped after it, tells refused as it stops (their events written)}. */
    int[] lateAfterStopForTest() { return new int[] {lateWritesRefused, lateCallbacksDropped, lateTellsRefused}; }

    /** Test-only: run once just as the next stop begins, after its barrier is set (a fixture's act "as it stops"). */
    void onStopBeginForTest(Runnable action) { onStopBegin = action; }

    private Runnable onStopBegin;

    /**
     * A sale's intent the Record holds with neither its sale nor its cancel is ambiguous: the server stopped between
     * taking the items and writing the coins, or before. It is reported for an operator as a {@code market.uncertain}
     * event and in the log, and never settled or replayed (M-06g).
     */
    private void reportOpenSales(SqliteCompanionStore database) {
        database.allWorldEvents(Set.of(MarketDesk.INTENT, MarketDesk.CANCEL, MarketDesk.RECEIVED, dev.kindred.core.market.MarketLedger.SALE,
                        dev.kindred.core.market.MarketLedger.BUY, "market.uncertain", dev.kindred.core.market.Auctions.DELIVERING, dev.kindred.core.market.Auctions.DELIVERED))
                .whenComplete((events, failure) -> handBack(() -> {
                    if (failure != null || !running) return;
                    var open = new java.util.LinkedHashMap<String, dev.kindred.core.record.WorldEvent>();
                    for (var e : events) {
                        if (e.kind().equals(MarketDesk.INTENT) || e.kind().equals(dev.kindred.core.market.Auctions.DELIVERING)) open.put(e.subject(), e);
                        else if (e.kind().equals(dev.kindred.core.market.MarketLedger.BUY) && !e.get("purchase", "").isEmpty()) open.put(e.get("purchase", ""), e);
                        else if (e.kind().equals(dev.kindred.core.market.MarketLedger.SALE)) open.remove(e.get("intent", ""));
                        else open.remove(e.subject());
                    }
                    for (var e : open.values()) {
                        String id = e.kind().equals(dev.kindred.core.market.MarketLedger.BUY) ? e.get("purchase", "") : e.subject();
                        KindredMod.LOGGER.error("Market {} {} by {} is unfinished: reconcile its items and coins by hand", e.kind(), id, e.actor());
                        record(dev.kindred.core.record.WorldEvent.recorded(server.getTicks(), System.currentTimeMillis(), e.world(), MarketDesk.UNCERTAIN, e.actor(), id, "",
                                java.util.Map.of("items", e.get("items", ""), "cents", e.get("cents", ""))));
                    }
                }));
    }

