    /**
     * The spawn hub (M-06f), operators only, in a faction world: its chunks made a safe zone in the World Record, the
     * border set to the settings' width round (0, 0) with a 20-block warning, and, if {@code build}, the hub's lighthouse
     * and market district built from the builder's generators on the ground at spawn (server setup, an operator's own
     * blocks, as /fill would place them).
     */
    int factionsHub(ServerCommandSource source, boolean build) {
        requireThread();
        if (!ready || !running) return reject(source, "Kindred is loading saved records.");
        if (!source.hasPermissionLevel(2)) return reject(source, "Only an operator sets the hub.");
        if (!factionsWorld()) return reject(source, "This world does not play Factions.");
        var settings = factions.settings();
        UUID by = source.getPlayer() == null ? null : source.getPlayer().getUuid();
        var chunks = dev.kindred.core.factions.SafeZones.hub(settings.safeRadius());
        record(dev.kindred.core.factions.SafeZones.zone(dev.kindred.core.factions.SafeZones.HUB, chunks, by, server.getTicks(), System.currentTimeMillis()));
        factions.applyBorders();
        int placed = 0;
        if (build) {
            var world = server.getOverworld();
            int ground = world.getTopY(net.minecraft.world.Heightmap.Type.MOTION_BLOCKING_NO_LEAVES, 0, 0);
            for (var part : dev.kindred.core.factions.SafeZones.plan()) {
                for (var block : part.blueprint().blocks()) {
                    var at = new BlockPos(part.origin().x() + block.at().x(), ground + part.origin().y() + block.at().y(), part.origin().z() + block.at().z());
                    try {
                        var state = net.minecraft.command.argument.BlockArgumentParser.block(
                                net.minecraft.registry.Registries.BLOCK.getReadOnlyWrapper(), block.spec().toString(), false).blockState();
                        if (world.setBlockState(at, state)) placed++;
                    } catch (Exception unknown) {
                        KindredMod.LOGGER.warn("Hub block {} not known; left out", block.spec());
                    }
                }
            }
        }
        feedback(source, "The hub is a safe zone (" + chunks.size() + " chunks); the border " + settings.border() + " across" + (build ? "; " + placed + " blocks of hub built" : "") + ".");
        return 1;
    }

    /** Whether {@code attacker} may strike {@code target} by the faction rules, in a faction world. */
    boolean factionsMayAttack(UUID attacker, UUID target) {
        requireThread();
        return factionsWorld() && factions.mayAttack(attacker, target);
    }

    /**
     * {@code who}'s faction request (M-06c), a person's or an AI player's alike, answered to {@code source}. Only in a
     * faction world.
     */
    FactionsService.Reply faction(ServerCommandSource source, UUID who, String verb, List<String> args) {
        requireThread();
        FactionsService.Reply reply;
        if (!ready || !running) reply = FactionsService.Reply.refused("Kindred is loading saved records.");
        else if (!factionsWorld()) reply = FactionsService.Reply.refused("This world does not play Factions.");
        else {
            var player = server.getPlayerManager().getPlayer(who);
            String world = player != null ? player.getServerWorld().getRegistryKey().getValue().toString() : source.getWorld().getRegistryKey().getValue().toString();
            BlockPos pos = player != null ? player.getBlockPos() : BlockPos.ofFloored(source.getPosition());
            reply = factions.request(who, verb.toLowerCase(java.util.Locale.ROOT), args, world, pos, this::playerByName, this::factionName);
            if (reply.accepted() && verb.equalsIgnoreCase("home") && player != null) reply = homeTravel(player, reply);
        }
        for (String line : reply.lines()) {
            if (reply.accepted()) feedback(source, line); else reject(source, line);
        }
        return reply;
    }

    /**
     * {@code /faction home} with free travel allowed on this server (mod-support decision 6): whoever asks is taken to its
     * faction's home, by the rule announced to everyone (D6). Forbidden (the default), home is only told. An AI player
     * never travels this way: no recorded skill uses it, and the lead approves one first.
     */
    private FactionsService.Reply homeTravel(ServerPlayerEntity player, FactionsService.Reply told) {
        if (!teleportAllowed()) return told;
        // An AI player's body, by its entry or by its kind: never taken.
        if (entryForPlayer(player.getUuid()) != null || player instanceof PreparedNativePlayer) return told;
        var faction = factions.book().of(player.getUuid()).orElse(null);
        if (faction == null || faction.home().isEmpty()) return told;
        String home = faction.home();
        int split = home.lastIndexOf(':');
        String[] xyz = split < 0 ? new String[0] : home.substring(split + 1).split(",");
        var world = split < 0 ? null : server.getWorld(net.minecraft.registry.RegistryKey.of(net.minecraft.registry.RegistryKeys.WORLD,
                net.minecraft.util.Identifier.tryParse(home.substring(0, split))));
        if (world == null || xyz.length != 3) return FactionsService.Reply.refused(faction.name() + "'s home is not a place: " + home);
        try {
            player.teleport(world, Integer.parseInt(xyz[0]) + 0.5, Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2]) + 0.5, player.getYaw(), player.getPitch());
        } catch (NumberFormatException failure) {
            return FactionsService.Reply.refused(faction.name() + "'s home is not a place: " + home);
        }
        return FactionsService.Reply.told(List.of("Teleported to " + faction.name() + "'s home (teleporting is allowed on this server, for everyone alike)."));
    }

    /** An online player's id by name, a person or an AI player. */
    private UUID playerByName(String name) {
        if (name == null || name.isBlank()) return null;
        var player = server.getPlayerManager().getPlayer(name.trim());
        return player == null ? null : player.getUuid();
    }

    /** A player's name for a faction reply: online, or the start of its id. */
    private String factionName(UUID player) {
        var online = server.getPlayerManager().getPlayer(player);
        return online != null ? online.getName().getString() : player.toString().substring(0, 8);
    }

    /** Whether every write to the World Record asked for so far is done. */
    boolean recordWritten() {
        requireThread();
        return recordFlush.isDone();
    }

    /** A player fell: a running duel it was in ends, the other the winner. */
    void playerFell(UUID playerId) {
        requireThread();
        matches.fallen(playerId).ifPresent(this::announce);
        // A death is told to everyone, and a player comes back at full health: what any player believed of its health
        // is gone with it (E-41a).
        forgetHealth(playerId);
    }

    /** Each native player's belief of {@code playerId}'s health forgotten: it is known to be full again. */
    void forgetHealth(UUID playerId) {
        requireThread();
        for (Entry entry : entries.values()) if (entry.nativeBody != null) entry.nativeBody.beliefs().forget(playerId);
    }

    /** A player left the game: a duel it was in is forfeited, or called off if it had not started. */
    void playerLeft(UUID playerId) {
        requireThread();
        if (factionsWorld()) {
            factions.disconnected(playerId);
            hud.left(playerId);
        }
        matches.departed(playerId).ifPresent(this::announce);
    }

    /** A match by its id or the start of it, as typed. */
    java.util.Optional<dev.kindred.core.match.MatchRegistry.Match> findMatch(String raw) {
        requireThread();
        return matches.find(raw);
    }

    /** Whether the match rule lets {@code attacker} strike {@code target} now, for a fixture. */
    boolean mayAttackForTest(UUID attacker, UUID target) {
        requireThread();
        return matches.mayAttack(attacker, target);
    }

    MatchPresenter presenter() {
        requireThread();
        return presenter;
    }

    List<dev.kindred.core.match.MatchRegistry.Match> matches() {
        requireThread();
        return matches.list();
    }

    /** The gates on a native player's next decision, in a line, for a fixture that finds it idle. */
    String nativeStatusLine(UUID id) {
        requireThread();
        Entry entry = id != null ? entries.get(id) : null;
        if (entry == null) return "no such player";
        var body = entry.nativeBody;
        String ticking = body == null ? "body=none" : "bodyTicks=" + body.ticksRun() + " age=" + body.entity().age + " removed=" + body.entity().isRemoved()
                + " listed=" + (server.getPlayerManager().getPlayer(body.entity().getUuid()) == body.entity()) + " connected=" + body.connected()
                // Whether the world it is in ticks it: a world ticks an entity only where its chunk is simulated.
                + " world=" + body.entity().getServerWorld().getRegistryKey().getValue().getPath()
                + " inWorld=" + body.entity().getServerWorld().getPlayers().contains(body.entity())
                + " lookup=" + (body.entity().getServerWorld().getEntity(body.entity().getUuid()) == body.entity())
                + " simulated=" + body.entity().getServerWorld().shouldTickEntity(body.entity().getBlockPos())
                + " forced=" + body.entity().getServerWorld().getForcedChunks().contains(body.entity().getChunkPos().toLong());
        return ticking + " phase=" + (entry.nativeState == null ? "none" : entry.nativeState.phase()) + " stop=" + entry.snapshot().stopLatched()
                + " runner=" + (entry.runner == null ? "none" : entry.runner.state()) + " busy=" + (entry.runner != null && runnerBusy(entry))
                + " workPending=" + entry.nativeWorkPending + " setupPending=" + entry.nativeSetupPending + " actionPending=" + entry.nativeActionPending
                + " activity=" + (entry.activity == null ? "none" : entry.activity.phase()) + " flushes=" + entry.activityFlush.isDone() + "/"
                + entry.nativeActionFlush.isDone() + " cancelling=" + (entry.arbiter != null && entry.arbiter.cancellationPending())
                + " hold=" + (entry.manualHoldUntilTick == Long.MIN_VALUE ? "none" : String.valueOf(entry.manualHoldUntilTick - server.getTicks())) + " edits=" + edits.autonomousEditsEnabled() + "/"
                + edits.protectionCompatibilityKnown() + " playstyle=" + entry.runtimeSettings.playstyleProfile() + " routine="
                + entry.cachedRoutineCandidates.size() + "/" + entry.routineRefreshPending + " build=" + (entry.build == null ? "none" : entry.build.progress())
                + " blocker=" + entry.blocker;
    }

    int cachedRoutineCandidatesCountForTest(UUID id) {
        Entry entry = entries.get(id);
        return entry == null ? 0 : entry.cachedRoutineCandidates.size();
    }

    long inventoryFingerprintForTest(UUID id) {
        Entry entry = entries.get(id);
        return entry == null ? 0L : entry.lastInventoryFingerprint;
    }

    int blocksScannedThisTickForTest() {
        return blocksScannedThisTick;
    }

